```java
// 在createFile方法中修改文件创建逻辑
private static void createFile(Scanner scanner) {
    if (!checkAuth()) return;

    String filename = getStringInput(scanner, "输入文件名: ");
    String content = getStringInput(scanner, "输入内容: ");

    if (filename.isEmpty() || content.isEmpty()) {
        System.out.println("文件名和内容不能为空！");
        return;
    }

    Path path = Paths.get(FILES_FOLDER + currentUser, filename);

    try {
        // 创建父目录
        Files.createDirectories(path.getParent());

        // 创建文件并设置权限
        if (Files.exists(path)) {
            System.out.println("文件已存在！");
            return;
        }

        // 写入文件内容
        Files.write(path, content.getBytes(StandardCharsets.UTF_8));

        // 设置操作系统级只读权限（Windows）
        if (System.getProperty("os.name").toLowerCase().contains("win")) {
            path.toFile().setReadOnly();
        }
        // 设置POSIX权限（Linux/Mac）
        else {
            Set<PosixFilePermission> permissions = PosixFilePermissions.fromString("r--r-----");
            Files.setPosixFilePermissions(path, permissions);
        }

        // 初始化应用权限：所有者只读，其他用户无权限
        Map<String, String> permissions = new HashMap<>();
        permissions.put(currentUser, "r");  // 默认只读
        filePermissions.put(filename, permissions);

        System.out.println("文件创建成功（只读权限）");
    } catch (IOException e) {
        System.out.println("创建文件失败: " + e.getMessage());
    }
}

// 修改checkPermissions方法
private static boolean checkPermissions(String filename, String required) {
    if (currentUser == null) return false;

    // 默认权限检查逻辑
    if (filePermissions.containsKey(filename)) {
        Map<String, String> perms = filePermissions.get(filename);
        // 检查显式权限
        if (perms.containsKey(currentUser)) {
            return perms.get(currentUser).contains(required);
        }
        // 默认拒绝其他用户
        return false;
    }
    // 兼容旧文件：默认允许所有者读写（可选）
    return isFileOwner(filename) && required.equals("r"); 
}
