// 新增权限保存方法
private static void savePermissions() {
    Path permPath = Paths.get(FILES_FOLDER, PERMISSIONS_FILE);
    try (BufferedWriter writer = Files.newBufferedWriter(permPath)) {
        for (Map.Entry<String, Map<String, String>> entry : filePermissions.entrySet()) {
            String filename = entry.getKey();
            for (Map.Entry<String, String> userPerm : entry.getValue().entrySet()) {
                writer.write(String.format("%s:%s:%s\n",
                    filename,
                    userPerm.getKey(),
                    userPerm.getValue()));
            }
        }
    } catch (IOException e) {
        System.out.println("警告：权限保存失败 - " + e.getMessage());
    }
}

// 新增权限加载方法
private static void loadPermissions() {
    Path permPath = Paths.get(FILES_FOLDER, PERMISSIONS_FILE);
    if (!Files.exists(permPath)) return;

    try (BufferedReader reader = Files.newBufferedReader(permPath)) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(":");
            if (parts.length != 3) continue;

            filePermissions
                .computeIfAbsent(parts[0], k -> new HashMap<>())
                .put(parts[1], parts[2]);
        }
    } catch (IOException e) {
        System.out.println("警告：权限加载失败 - " + e.getMessage());
    }
}

