```java
private static void handleLogin(Scanner scanner) {
    if (AuthService.login(scanner)) {
        mainFunctionLoop(scanner);
    }
}

private static void mainFunctionLoop(Scanner scanner) {
    while (AuthService.isLoggedIn()) {
        FileService.showMainMenu();
        int choice = InputUtils.getIntInput(scanner, "请选择操作: ");
        scanner.nextLine();

        switch (choice) {
            case 1 -> AuthService.logout();
            case 2 -> FileService.createFile(scanner);
            case 3 -> FileService.deleteFile(scanner);
            case 4 -> FileService.readFile(scanner);
            case 5 -> FileService.updateFile(scanner);
            case 6 -> FileService.renameFile(scanner);
            case 7 -> PermissionManager.changePermission(scanner);
            case 8 -> FileService.listFiles();
            case 9 -> FileService.viewFileAttributes(scanner);
            case 10 -> { 
                PermissionManager.savePermissions();
                System.exit(0);
            }
            default -> System.out.println("无效操作！");
        }
    }
}
```

