public static void registerUser(Scanner scanner) {
    String username = InputUtils.getStringInput(scanner, "请输入用户名: ");
    String password = InputUtils.getStringInput(scanner, "请输入密码: ");

    // 输入校验
    if (username.isEmpty() || password.isEmpty()) {
        System.out.println("用户名和密码不能为空！");
        return;
    }
    if (password.length() < 6) {
        System.out.println("密码长度至少6位！");
        return;
    }

    // 检查用户目录是否已存在
    Path userDir = Paths.get(Constants.USERS_FOLDER, username);
    if (Files.exists(userDir)) {
        System.out.println("用户名已存在！");
        return;
    }

    try {
        // 创建用户目录
        Files.createDirectories(userDir);
        // 保存哈希后的密码
        UserCredentials.saveCredentials(username, password);
        System.out.println("注册成功！");
        FileOperationLog.log("REG_USER", "SUCCESS", "用户注册: " + username);
    } catch (IOException e) {
        System.out.println("注册失败: " + e.getMessage());
        FileOperationLog.log("REG_USER", "FAILED", "错误: " + e.getMessage());
    }
}
```

