import com.filemanager.util.HashUtils;
import java.nio.file.*;

public class UserCredentials {
    // 保存用户凭证（密码哈希）
    public static void saveCredentials(String username, String password) throws IOException {
        Path credentialPath = getCredentialPath(username);
        String hashedPassword = HashUtils.hashPassword(password);
        Files.writeString(credentialPath, hashedPassword, StandardOpenOption.CREATE);
    }

    // 读取用户凭证（哈希密码）
    public static String getHashedPassword(String username) throws IOException {
        Path credentialPath = getCredentialPath(username);
        if (!Files.exists(credentialPath)) {
            throw new IOException("用户凭证文件不存在");
        }
        return Files.readString(credentialPath);
    }

    // 构建凭证文件路径
    private static Path getCredentialPath(String username) {
        return Paths.get(Constants.USERS_FOLDER, username, "credentials.dat");
    }
}
```

