public static void deleteFile(Scanner scanner) {
    if (!AuthService.isLoggedIn()) return;

    String filename = InputUtils.getStringInput(scanner, "输入要删除的文件名: ");
    Path filePath = Paths.get(Constants.FILES_FOLDER, AuthService.getCurrentUser(), filename);

    try {
        if (Files.deleteIfExists(filePath)) {
            PermissionManager.removeFilePermissions(filename); // 清理权限记录
            FileOperationLog.log("DELETE_FILE", "SUCCESS", 
                "用户 " + AuthService.getCurrentUser() + " 删除文件: " + filename);
            System.out.println("文件已删除。");
        } else {
            System.out.println("文件未找到。");
            FileOperationLog.log("DELETE_FILE", "FAILED", 
                "用户尝试删除不存在的文件: " + filename);
        }
    } catch (IOException e) {
        System.out.println("删除失败: " + e.getMessage());
        FileOperationLog.log("DELETE_FILE", "FAILED", 
            "错误: " + e.getMessage());
    }
}
```

