```java
public static void readFile(Scanner scanner) {
    if (!AuthService.isLoggedIn()) return;

    String filename = InputUtils.getStringInput(scanner, "输入文件: ");
    Path filePath = Paths.get(Constants.FILES_FOLDER, AuthService.getCurrentUser(), filename);

    if (!Files.exists(filePath)) {
        System.out.println("文件不存在！");
        return;
    }

    if (!PermissionManager.checkReadPermission(filename, AuthService.getCurrentUser())) {
        System.out.println("无读取权限！");
        return;
    }

    try {
        String content = Files.readString(filePath, StandardCharsets.UTF_8);
        System.out.println("文件内容:");
        for (int i = 0; i < content.length(); i += Constants.FILE_CONTENT_LINE_LENGTH) {
            int endIndex = Math.min(i + Constants.FILE_CONTENT_LINE_LENGTH, content.length());
            System.out.println(content.substring(i, endIndex));
        }
        FileOperationLog.log("READ_FILE", "SUCCESS", 
            "用户 " + AuthService.getCurrentUser() + " 读取文件: " + filename);
    } catch (IOException e) {
        System.out.println("读取失败: " + e.getMessage());
        FileOperationLog.log("READ_FILE", "FAILED", 
            "错误: " + e.getMessage());
    }
}
```

