public class DateUtils {
    // 线程安全的日期格式化（Java 8+ 使用 DateTimeFormatter）
    private static final DateTimeFormatter LOG_DATE_FORMATTER = 
        DateTimeFormatter.ofPattern(Constants.LOG_DATE_FORMAT);

    // 旧版 SimpleDateFormat（需结合 ThreadLocal 保证线程安全）
    private static final ThreadLocal<SimpleDateFormat> FILE_TIME_FORMATTER = 
        ThreadLocal.withInitial(() -> new SimpleDateFormat(Constants.LOG_DATE_FORMAT));

    /**
     * 将 FileTime 转换为格式化字符串（如 "2023-10-01 14:30:00"）
     */
    public static String formatFileTime(FileTime fileTime) {
        return fileTime.toInstant()
                      .atZone(ZoneId.systemDefault())
                      .format(LOG_DATE_FORMATTER);
    }

    /**
     * 兼容旧版的格式化方法（使用 ThreadLocal 解决线程安全问题）
     */
    public static String legacyFormatFileTime(FileTime fileTime) {
        Date date = new Date(fileTime.toMillis());
        return FILE_TIME_FORMATTER.get().format(date);
    }
}
