```java
package com.filemanager.auth;

import com.filemanager.constants.Constants;
import com.filemanager.util.SecurityUtil;
import java.nio.file.*;

public class UserAuthenticator {
    public boolean registerUser(String username, String password) {
        Path userFolder = Paths.get(Constants.USERS_FOLDER + username);
        if (Files.exists(userFolder)) {
            System.out.println("用户名已存在！");
            return false;
        }

        try {
            Files.createDirectories(userFolder);
            SecurityUtil.saveCredentials(username, password);
            return true;
        } catch (IOException e) {
            System.out.println("注册失败: " + e.getMessage());
            return false;
        }
    }

    public boolean login(String username, String password) {
        Path credentialFile = Paths.get(Constants.USERS_FOLDER + username + "/credentials.dat");
        if (!Files.exists(credentialFile)) return false;

        try {
            String storedHash = Files.readString(credentialFile);
            return SecurityUtil.validatePassword(password, storedHash);
        } catch (IOException e) {
            return false;
        }
    }
}
