package com.filemanager.core;

import com.filemanager.constants.Constants;
import java.util.*;
import java.nio.file.*;

public class PermissionManager {
    private Map<String, Map<String, String>> permissions = new HashMap<>();
    private String currentUser;

    public void setCurrentUser(String user) {
        this.currentUser = user;
    }

    public boolean checkPermission(String filename, String operation) {
        if (isOwner(filename)) return true;
        return permissions.getOrDefault(filename, new HashMap<>())
               .getOrDefault(currentUser, "").contains(operation);
    }

    private boolean isOwner(String filename) {
        Path path = Paths.get(Constants.FILES_FOLDER + currentUser, filename);
        return Files.exists(path);
    }

