### 6. 安全工具 `SecurityUtil.java`
```java
package com.filemanager.util;

import com.filemanager.constants.Constants;
import java.security.*;
import java.nio.file.*;

public class SecurityUtil {
    public static void saveCredentials(String username, String password) throws IOException {
        Path path = Paths.get(Constants.USERS_FOLDER + username + "/credentials.dat");
        Files.writeString(path, hashPassword(password), StandardOpenOption.CREATE);
    }

    public static boolean validatePassword(String input, String storedHash) {
        return hashPassword(input).equals(storedHash);
    }

    private static String hashPassword(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(password.getBytes());
            return bytesToHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

