## 核心功能实现

### 1. 文件加密存储服务

```java
@Service
public class FileEncryptionService {

    @Value("${encryption.secret-key}")
    private String secretKey;

    @Value("${encryption.salt}")
    private String salt;

    public void encryptFile(MultipartFile file, String outputPath) throws IOException {
        try {
            Key key = generateKey();
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.ENCRYPT_MODE, key);

            try (InputStream is = file.getInputStream();
                 OutputStream os = new FileOutputStream(outputPath);
                 CipherOutputStream cos = new CipherOutputStream(os, cipher)) {

                byte[] buffer = new byte[8192];
                int count;
                while ((count = is.read(buffer)) > 0) {
                    cos.write(buffer, 0, count);
                }
            }
        } catch (Exception e) {
            throw new IOException("文件加密失败", e);
        }
    }

    public void decryptFile(String inputPath, OutputStream outputStream) throws IOException {
        try {
            Key key = generateKey();
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.DECRYPT_MODE, key);

            try (InputStream is = new FileInputStream(inputPath);
                 CipherInputStream cis = new CipherInputStream(is, cipher)) {

                byte[] buffer = new byte[8192];
                int count;
                while ((count = cis.read(buffer)) > 0) {
                    outputStream.write(buffer, 0, count);
                }
            }
        } catch (Exception e) {
            throw new IOException("文件解密失败", e);
        }
    }

    private Key generateKey() throws Exception {
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec spec = new PBEKeySpec(secretKey.toCharArray(), salt.getBytes(), 65536, 256);
        SecretKey tmp = factory.generateSecret(spec);
        return new SecretKeySpec(tmp.getEncoded(), "AES");
    }
}
```

### 2. 权限验证服务

```java
@Service
public class PermissionService {

    @Autowired
    private PermissionRepository permissionRepository;

    public boolean hasFilePermission(User user, FileEntity file, PermissionLevel requiredLevel) {
        // 管理员拥有所有权限
        if (user.getRole() == UserRole.ADMIN) {
            return true;
        }

        // 文件所有者拥有所有权限
        if (file.getOwner().getId().equals(user.getId())) {
            return true;
        }

        // 检查权限表
        Permission permission = permissionRepository
            .findByUserAndFile(user, file)
            .orElse(null);

        return permission != null && 
               permission.getLevel().getValue() >= requiredLevel.getValue();
    }

    public boolean hasFolderPermission(User user, Folder folder, PermissionLevel requiredLevel) {
        // 管理员拥有所有权限
        if (user.getRole() == UserRole.ADMIN) {
            return true;
        }

        // 文件夹所有者拥有所有权限
        if (folder.getOwner().getId().equals(user.getId())) {
            return true;
        }

        // 检查权限表
        Permission permission = permissionRepository
            .findByUserAndFolder(user, folder)
            .orElse(null);

        return permission != null && 
               permission.getLevel().getValue() >= requiredLevel.getValue();
    }
}
```

### 3. 文件服务核心实现

```java
@Service
public class FileService {

    @Autowired
    private FileRepository fileRepository;

    @Autowired
    private FolderRepository folderRepository;

    @Autowired
    private PermissionService permissionService;

    @Autowired
    private FileEncryptionService encryptionService;

    @Value("${file.storage.path}")
    private String storagePath;

    public FileEntity uploadFile(MultipartFile multipartFile, Long folderId, User user) 
            throws IOException {

        // 验证文件夹权限
        if (folderId != null) {
            Folder folder = folderRepository.findById(folderId)
                .orElseThrow(() -> new ResourceNotFoundException("文件夹不存在"));

            if (!permissionService.hasFolderPermission(user, folder, PermissionLevel.WRITE)) {
                throw new AccessDeniedException("没有权限在此文件夹上传文件");
            }
        }

        // 生成唯一文件名和路径
        String originalFilename = multipartFile.getOriginalFilename();
        String fileExtension = FilenameUtils.getExtension(originalFilename);
        String uniqueFilename = UUID.randomUUID().toString() + "." + fileExtension;
        String filePath = Paths.get(storagePath, uniqueFilename).toString();
        String encryptedFilePath = filePath + ".enc";

        // 加密并存储文件
        encryptionService.encryptFile(multipartFile, encryptedFilePath);

        // 创建文件记录
        FileEntity file = new FileEntity();
        file.setFilename(uniqueFilename);
        file.setOriginalName(originalFilename);
        file.setPath(filePath);
        file.setEncryptedPath(encryptedFilePath);
        file.setSize(multipartFile.getSize());
        file.setType(determineFileType(fileExtension));
        file.setOwner(user);
        file.setFolder(folderId != null ? folderRepository.getOne(folderId) : null);
        file.setEncrypted(true);

        return fileRepository.save(file);
    }

    public Resource downloadFile(Long fileId, User user) throws IOException {
        FileEntity file = fileRepository.findById(fileId)
            .orElseThrow(() -> new ResourceNotFoundException("文件不存在"));

        if (!permissionService.hasFilePermission(user, file, PermissionLevel.READ)) {
            throw new AccessDeniedException("没有权限下载此文件");
        }

        // 创建临时文件用于解密
        File tempFile = File.createTempFile("download", null);
        tempFile.deleteOnExit();

        try (FileOutputStream fos = new FileOutputStream(tempFile)) {
            encryptionService.decryptFile(file.getEncryptedPath(), fos);
        }

        return new FileSystemResource(tempFile);
    }

    public void deleteFile(Long fileId, User user) {
        FileEntity file = fileRepository.findById(fileId)
            .orElseThrow(() -> new ResourceNotFoundException("文件不存在"));

        if (!permissionService.hasFilePermission(user, file, PermissionLevel.DELETE)) {
            throw new AccessDeniedException("没有权限删除此文件");
        }

        // 删除物理文件
        try {
            Files.deleteIfExists(Paths.get(file.getEncryptedPath()));
        } catch (IOException e) {
            throw new FileStorageException("无法删除物理文件", e);
        }

        // 删除数据库记录
        fileRepository.delete(file);
    }

    // 其他方法：移动文件、重命名、获取文件列表等
}
```

