这个警告表明您的应用程序中存在**事件监听器泄漏**问题。这通常是由于在同一个 Socket 上重复添加事件监听器而没有正确移除导致的。

## 问题原因

在 Express + SQLite 应用中，常见的原因包括：
1. 每次请求都创建新的数据库连接
2. 事件监听器在循环或频繁调用的函数中重复添加
3. 数据库连接没有正确关闭和重用

## 解决方案

### 1. 改进的数据库连接管理

```javascript
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const cors = require('cors');
const app = express();

// 单例数据库连接
let db = null;

function getDatabaseConnection() {
    if (!db) {
        db = new sqlite3.Database('./waterfall.db', (err) => {
            if (err) {
                console.error('Database connection error:', err.message);
            } else {
                console.log('Connected to SQLite database');
                // 设置最大监听器数量
                db.configured = true;
            }
        });

        // 配置最大监听器数量
        db.setMaxListeners(15); // 适当增加限制

        // 处理数据库错误
        db.on('error', (err) => {
            console.error('Database error:', err);
        });
    }
    return db;
}

// 初始化数据库
function initializeDatabase() {
    const database = getDatabaseConnection();

    return new Promise((resolve, reject) => {
        database.run(`CREATE TABLE IF NOT EXISTS waterfall (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )`, (err) => {
            if (err) {
                console.error('Table creation error:', err);
                reject(err);
            } else {
                console.log('Waterfall table ready');
                resolve();
            }
        });
    });
}

app.use(cors());
app.use(express.json());

// 请求计数器和连接管理
let requestCount = 0;

// 全局错误处理中间件
app.use((req, res, next) => {
    requestCount++;
    console.log(`Request ${requestCount}: ${req.method} ${req.path}`);

    // 清理监听器以防止内存泄漏
    req.on('close', () => {
        requestCount--;
    });

    next();
});

// 获取所有动态 - 使用连接池思想
app.get('/api/waterfall', async (req, res) => {
    try {
        const db = getDatabaseConnection();

        // 使用 Promise 包装数据库查询
        const rows = await new Promise((resolve, reject) => {
            db.all('SELECT id, title, content, created_at FROM waterfall ORDER BY id DESC', [], (err, rows) => {
                if (err) {
                    console.error('Query error:', err);
                    reject(err);
                } else {
                    resolve(rows);
                }
            });
        });

        res.json(rows);
    } catch (error) {
        console.error('API Error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// 添加新动态
app.post('/api/waterfall', async (req, res) => {
    try {
        const { title, content } = req.body;

        if (!title || !content) {
            return res.status(400).json({ error: 'Title and content are required' });
        }

        const db = getDatabaseConnection();

        const result = await new Promise((resolve, reject) => {
            db.run('INSERT INTO waterfall (title, content) VALUES (?, ?)', [title, content], function(err) {
                if (err) {
                    console.error('Insert error:', err);
                    reject(err);
                } else {
                    resolve({ id: this.lastID });
                }
            });
        });

        res.json({ id: result.id, message: 'Record added successfully' });
    } catch (error) {
        console.error('API Error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// 健康检查端点
app.get('/health', (req, res) => {
    const db = getDatabaseConnection();

    db.get('SELECT 1 as test', (err) => {
        if (err) {
            return res.status(503).json({ 
                status: 'ERROR', 
                database: 'disconnected',
                timestamp: new Date().toISOString()
            });
        }

        res.json({ 
            status: 'OK', 
            database: 'connected',
            requests: requestCount,
            timestamp: new Date().toISOString()
        });
    });
});

// 优雅关闭处理
function gracefulShutdown() {
    console.log('Shutting down gracefully...');

    if (db) {
        db.close((err) => {
            if (err) {
                console.error('Error closing database:', err);
            } else {
                console.log('Database connection closed.');
            }
            process.exit(0);
        });
    } else {
        process.exit(0);
    }
}

process.on('SIGINT', gracefulShutdown);
process.on('SIGTERM', gracefulShutdown);

// 处理未捕获的异常
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown();
});

// 启动服务器
const PORT = process.env.PORT || 3000;

async function startServer() {
    try {
        await initializeDatabase();

        app.listen(PORT, '0.0.0.0', () => {
            console.log(`Server running on http://0.0.0.0:${PORT}`);
            console.log(`Health check: http://localhost:${PORT}/health`);
        });
    } catch (error) {
        console.error('Failed to start server:', error);
        process.exit(1);
    }
}

startServer();
```

