### 4. 时间片轮转(RR)算法

```c
void RoundRobin(PCB processes[], int n, int time_quantum) {
    int remaining_time[MAX_PROCESS];
    int current_time = 0, completed = 0;
    float total_waiting = 0, total_turnaround = 0;

    // 初始化剩余时间
    for (int i = 0; i < n; i++) {
        remaining_time[i] = processes[i].burst_time;
        processes[i].start_time = -1;
    }

    printf("\n=== 时间片轮转调度(时间片=%d) ===\n", time_quantum);

    while (completed < n) {
        int all_done = 1;

        for (int i = 0; i < n; i++) {
            if (remaining_time[i] > 0 && processes[i].arrival_time <= current_time) {
                all_done = 0;

                if (processes[i].start_time == -1) {
                    processes[i].start_time = current_time;
                }

                // 执行一个时间片
                if (remaining_time[i] > time_quantum) {
                    current_time += time_quantum;
                    remaining_time[i] -= time_quantum;
                } else {
                    current_time += remaining_time[i];
                    processes[i].finish_time = current_time;
                    processes[i].waiting_time = processes[i].finish_time - 
                                              processes[i].arrival_time - 
                                              processes[i].burst_time;
                    processes[i].turnaround_time = processes[i].finish_time - 
                                                 processes[i].arrival_time;

                    total_waiting += processes[i].waiting_time;
                    total_turnaround += processes[i].turnaround_time;

                    remaining_time[i] = 0;
                    completed++;
                }
            }
        }

        if (all_done) current_time++;
    }

    // 输出结果
    printf("PID\t名称\t到达\t运行\t开始\t完成\t等待\t周转\n");
    for (int i = 0; i < n; i++) {
        printf("%d\t%s\t%d\t%d\t%d\t%d\t%d\t%d\n",
               processes[i].pid, processes[i].name, processes[i].arrival_time,
               processes[i].burst_time, processes[i].start_time, processes[i].finish_time,
               processes[i].waiting_time, processes[i].turnaround_time);
    }

    printf("\n平均等待时间: %.2f\n", total_waiting/n);
    printf("平均周转时间: %.2f\n", total_turnaround/n);
}
```

