```c
#include "game_common.h"

// 创建消息队列
int create_msgq() {
    key_t key = ftok(".", 'G');
    int msgid = msgget(key, IPC_CREAT | 0666);
    if (msgid == -1) {
        perror("msgget failed");
        exit(1);
    }
    return msgid;
}

// 获取消息队列
int get_msgq() {
    key_t key = ftok(".", 'G');
    int msgid = msgget(key, 0666);
    if (msgid == -1) {
        perror("msgget failed");
        exit(1);
    }
    return msgid;
}

// 判断游戏结果
int judge_game(int choice1, int choice2) {
    if (choice1 == choice2) {
        return DRAW;
    }

    if ((choice1 == ROCK && choice2 == SCISSORS) ||
        (choice1 == SCISSORS && choice2 == PAPER) ||
        (choice1 == PAPER && choice2 == ROCK)) {
        return WIN; // player1赢
    } else {
        return LOSE; // player1输
    }
}

// 将选择转换为字符串
const char* choice_to_str(int choice) {
    switch(choice) {
        case ROCK: return "石头";
        case SCISSORS: return "剪刀";
        case PAPER: return "布";
        default: return "未知";
    }
}

// 打印结果
void print_result(int choice1, int choice2, int result) {
    printf("\n=== 游戏结果 ===\n");
    printf("玩家1: %s\n", choice_to_str(choice1));
    printf("玩家2: %s\n", choice_to_str(choice2));

    switch(result) {
        case WIN:
            printf("结果: 玩家1获胜!\n");
            break;
        case LOSE:
            printf("结果: 玩家2获胜!\n");
            break;
        case DRAW:
            printf("结果: 平局!\n");
            break;
    }
    printf("================\n\n");
}
