```c
#include "game_common.h"

int main() {
    int msgid = get_msgq();
    struct game_msg msg;
    struct result_msg result;

    printf("=== 玩家1 ===\n");

    while(1) {
        printf("\n请选择:\n");
        printf("1. 石头\n");
        printf("2. 剪刀\n");
        printf("3. 布\n");
        printf("0. 退出游戏\n");
        printf("请输入选择: ");

        int choice;
        scanf("%d", &choice);

        if (choice == 0) {
            printf("玩家1退出游戏\n");
            break;
        }

        if (choice < 1 || choice > 3) {
            printf("无效选择，请重新输入\n");
            continue;
        }

        // 发送玩家1的选择
        msg.mtype = MSG_TYPE_PLAYER1;
        msg.choice = choice;
        msg.player_id = 1;
        strcpy(msg.player_name, "玩家1");

        if (msgsnd(msgid, &msg, sizeof(msg) - sizeof(long), 0) == -1) {
            perror("msgsnd failed");
            exit(1);
        }

        printf("已发送选择: %s\n", choice_to_str(choice));

        // 等待裁判结果
        if (msgrcv(msgid, &result, sizeof(result) - sizeof(long), MSG_TYPE_RESULT, 0) == -1) {
            perror("msgrcv failed");
            exit(1);
        }

        print_result(result.player1_choice, result.player2_choice, result.result);
        printf("裁判消息: %s\n", result.message);
    }

    return 0;
}
