## 裁判程序 (judge.c)

```c
#include "game_common.h"

int main() {
    int msgid = create_msgq();
    struct game_msg player1_msg, player2_msg;
    struct result_msg result_msg;

    printf("=== 裁判程序启动 ===\n");
    printf("等待玩家连接...\n");

    while(1) {
        // 等待玩家1的选择
        if (msgrcv(msgid, &player1_msg, sizeof(player1_msg) - sizeof(long), MSG_TYPE_PLAYER1, 0) == -1) {
            perror("msgrcv player1 failed");
            break;
        }

        printf("收到玩家1的选择: %s\n", choice_to_str(player1_msg.choice));

        // 等待玩家2的选择
        if (msgrcv(msgid, &player2_msg, sizeof(player2_msg) - sizeof(long), MSG_TYPE_PLAYER2, 0) == -1) {
            perror("msgrcv player2 failed");
            break;
        }

        printf("收到玩家2的选择: %s\n", choice_to_str(player2_msg.choice));

        // 判断游戏结果
        int game_result = judge_game(player1_msg.choice, player2_msg.choice);

        // 准备结果消息
        result_msg.mtype = MSG_TYPE_RESULT;
        result_msg.player1_choice = player1_msg.choice;
        result_msg.player2_choice = player2_msg.choice;
        result_msg.result = game_result;

        // 设置结果消息
        switch(game_result) {
            case WIN:
                snprintf(result_msg.message, sizeof(result_msg.message), 
                        "玩家1的%s 战胜 玩家2的%s", 
                        choice_to_str(player1_msg.choice), 
                        choice_to_str(player2_msg.choice));
                break;
            case LOSE:
                snprintf(result_msg.message, sizeof(result_msg.message), 
                        "玩家2的%s 战胜 玩家1的%s", 
                        choice_to_str(player2_msg.choice), 
                        choice_to_str(player1_msg.choice));
                break;
            case DRAW:
                snprintf(result_msg.message, sizeof(result_msg.message), 
                        "双方都是%s，平局!", 
                        choice_to_str(player1_msg.choice));
                break;
        }

        // 发送结果给两个玩家（发送两次，确保每个玩家都能收到）
        if (msgsnd(msgid, &result_msg, sizeof(result_msg) - sizeof(long), 0) == -1) {
            perror("msgsnd result failed");
            break;
        }

        // 再发送一次，确保两个玩家都能收到
        if (msgsnd(msgid, &result_msg, sizeof(result_msg) - sizeof(long), 0) == -1) {
            perror("msgsnd result failed");
            break;
        }

        printf("裁判判定: %s\n", result_msg.message);

        // 将结果写入文件
        FILE *fp = fopen("result.txt", "a");
        if (fp) {
            fprintf(fp, "玩家1: %s, 玩家2: %s, 结果: %s\n",
                    choice_to_str(player1_msg.choice),
                    choice_to_str(player2_msg.choice),
                    result_msg.message);
            fclose(fp);
        }
    }

    // 清理消息队列
    msgctl(msgid, IPC_RMID, NULL);
    printf("裁判程序结束\n");

    return 0;
}
```

