import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int M = scanner.nextInt();

        int[] height = new int[N + 1]; // 1-based indexing
        for (int i = 1; i <= N; i++) {
            height[i] = scanner.nextInt();
        }

        for (int q = 0; q < M; q++) {
            int op = scanner.nextInt();
            if (op == 1) {
                // 修改操作
                int k = scanner.nextInt();
                int h = scanner.nextInt();
                updateHeight(height, k, h);
            } else {
                // 查询操作
                int L = scanner.nextInt();
                int R = scanner.nextInt();
                int result = queryGuardPeaks(height, L, R);
                System.out.println(result);
            }
        }

        scanner.close();
    }

    /**
     * 修改山峰高度
     * @param height 山峰高度数组
     * @param k 要修改的山峰位置
     * @param h 新的高度
     */
    public static void updateHeight(int[] height, int k, int h) {
        height[k] = h;
    }

    /**
     * 查询区间内的守护峰数量
     * @param height 山峰高度数组
     * @param L 区间左端点
     * @param R 区间右端点
     * @return 守护峰的数量
     */
    public static int queryGuardPeaks(int[] height, int L, int R) {
        // 区间长度小于3时没有守护峰
        if (R - L + 1 < 3) {
            return 0;
        }

        int count = 0;
        // 遍历区间内部的山峰（不包含两端）
        for (int i = L + 1; i <= R - 1; i++) {
            if (isGuardPeak(height, i)) {
                count++;
            }
        }
        return count;
    }

    /**
     * 判断指定位置是否是守护峰
     * @param height 山峰高度数组
     * @param index 要判断的位置
     * @return 如果是守护峰返回true，否则返回false
     */
    public static boolean isGuardPeak(int[] height, int index) {
        return height[index] > height[index - 1] && height[index] > height[index + 1];
    }
}
