```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define BUFFER_SIZE 1024

// 使用C语言库函数实现文件备份
void backup_with_library_functions(const char* source_file, const char* target_file) {
    printf("使用库函数进行文件备份...\n");
    printf("源文件: %s\n", source_file);
    printf("目标文件: %s\n", target_file);

    FILE* source_fp = NULL;
    FILE* target_fp = NULL;
    char buffer[BUFFER_SIZE];
    size_t bytes_read;

    // 打开源文件（只读模式）
    source_fp = fopen(source_file, "rb");
    if (source_fp == NULL) {
        perror("无法打开源文件");
        return;
    }

    // 打开目标文件（写入模式，如果不存在则创建）
    target_fp = fopen(target_file, "wb");
    if (target_fp == NULL) {
        perror("无法创建目标文件");
        fclose(source_fp);
        return;
    }

    // 复制文件内容
    size_t total_bytes = 0;
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, source_fp)) > 0) {
        size_t bytes_written = fwrite(buffer, 1, bytes_read, target_fp);
        if (bytes_written != bytes_read) {
            perror("写入文件时发生错误");
            break;
        }
        total_bytes += bytes_written;
    }

    // 检查读取错误
    if (ferror(source_fp)) {
        perror("读取文件时发生错误");
    }

    // 关闭文件
    fclose(source_fp);
    fclose(target_fp);

    printf("文件备份完成！总共复制了 %zu 字节\n\n", total_bytes);
}

// 使用系统调用函数实现文件备份
void backup_with_system_calls(const char* source_file, const char* target_file) {
    printf("使用系统调用进行文件备份...\n");
    printf("源文件: %s\n", source_file);
    printf("目标文件: %s\n", target_file);

    int source_fd = -1;
    int target_fd = -1;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // 打开源文件（只读模式）
    source_fd = open(source_file, O_RDONLY);
    if (source_fd == -1) {
        perror("无法打开源文件");
        return;
    }

    // 获取源文件权限
    struct stat file_stat;
    if (fstat(source_fd, &file_stat) == -1) {
        perror("无法获取文件信息");
        close(source_fd);
        return;
    }

    // 创建目标文件（读写模式，如果不存在则创建，设置与源文件相同的权限）
    target_fd = open(target_file, O_WRONLY | O_CREAT | O_TRUNC, file_stat.st_mode);
    if (target_fd == -1) {
        perror("无法创建目标文件");
        close(source_fd);
        return;
    }

    // 复制文件内容
    off_t total_bytes = 0;
    while ((bytes_read = read(source_fd, buffer, BUFFER_SIZE)) > 0) {
        ssize_t bytes_written = write(target_fd, buffer, bytes_read);
        if (bytes_written != bytes_read) {
            perror("写入文件时发生错误");
            break;
        }
        total_bytes += bytes_written;
    }

    // 检查读取错误
    if (bytes_read == -1) {
        perror("读取文件时发生错误");
    }

    // 关闭文件描述符
    close(source_fd);
    close(target_fd);

    printf("文件备份完成！总共复制了 %ld 字节\n\n", total_bytes);
}

