    printf("%c", (mode & S_IRUSR) ? 'r' : '-');
    printf("%c", (mode & S_IWUSR) ? 'w' : '-');
    printf("%c", (mode & S_IXUSR) ? 'x' : '-');

    // 组权限
    printf("%c", (mode & S_IRGRP) ? 'r' : '-');
    printf("%c", (mode & S_IWGRP) ? 'w' : '-');
    printf("%c", (mode & S_IXGRP) ? 'x' : '-');

    // 其他用户权限
    printf("%c", (mode & S_IROTH) ? 'r' : '-');
    printf("%c", (mode & S_IWOTH) ? 'w' : '-');
    printf("%c", (mode & S_IXOTH) ? 'x' : '-');

    printf(" (%04o)\n", mode & 0777);
}

// 显示文件详细信息
void display_file_info(const char* filename) {
    struct stat file_stat;

    if (stat(filename, &file_stat) == -1) {
        perror("无法获取文件信息");
        return;
    }

    printf("文件: %s\n", filename);
    display_file_permissions(file_stat.st_mode);
    printf("文件大小: %ld 字节\n", file_stat.st_size);
    printf("最后访问: %s", ctime(&file_stat.st_atime));
    printf("最后修改: %s", ctime(&file_stat.st_mtime));
    printf("最后状态改变: %s", ctime(&file_stat.st_ctime));
    printf("inode: %ld\n", file_stat.st_ino);
    printf("硬链接数: %ld\n", file_stat.st_nlink);
    printf("\n");
}

// 创建文件
void create_file(const char* filename) {
    printf("创建文件: %s\n", filename);

    int fd = open(filename, O_CREAT | O_EXCL, 0644);
    if (fd == -1) {
        if (errno == EEXIST) {
            printf("文件已存在！\n");
        } else {
            perror("创建文件失败");
        }
        return;
    }

    close(fd);
    printf("文件创建成功！\n");
    display_file_info(filename);
}

// 写入文件
void write_to_file(const char* filename, const char* content) {
    printf("写入文件: %s\n", filename);

    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("打开文件失败");
        return;
    }

    ssize_t bytes_written = write(fd, content, strlen(content));
    if (bytes_written == -1) {
        perror("写入文件失败");
    } else {
        printf("成功写入 %zd 字节到文件\n", bytes_written);
    }

    close(fd);
    display_file_info(filename);
}

// 读取文件
void read_from_file(const char* filename) {
    printf("读取文件: %s\n", filename);

    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("打开文件失败");
        return;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("文件内容:\n");
    printf("----------------------------------------\n");

    while ((bytes_read = read(fd, buffer, BUFFER_SIZE - 1)) > 0) {
        buffer[bytes_read] = '\0';
        printf("%s", buffer);
    }

    if (bytes_read == -1) {
        perror("读取文件失败");
    }

    printf("\n----------------------------------------\n");
    close(fd);
}

// 追加内容到文件
void append_to_file(const char* filename, const char* content) {
    printf("追加内容到文件: %s\n", filename);

    int fd = open(filename, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        perror("打开文件失败");
        return;
    }

    ssize_t bytes_written = write(fd, content, strlen(content));
    if (bytes_written == -1) {
        perror("追加内容失败");
    } else {
        printf("成功追加 %zd 字节到文件\n", bytes_written);
    }

    close(fd);
    read_from_file(filename);
}

// 改变文件权限
void change_file_permissions(const char* filename, mode_t mode) {
    printf("改变文件权限: %s -> %04o\n", filename, mode);

    if (chmod(filename, mode) == -1) {
        perror("改变文件权限失败");
        return;
    }

    printf("文件权限修改成功！\n");
    display_file_info(filename);
}

// 删除文件
void delete_file(const char* filename) {
    printf("删除文件: %s\n", filename);

    if (unlink(filename) == -1) {
        perror("删除文件失败");
        return;
    }

    printf("文件删除成功！\n");
}

// 创建目录
void create_directory(const char* dirname) {
    printf("创建目录: %s\n", dirname);

    if (mkdir(dirname, 0755) == -1) {
        perror("创建目录失败");
        return;
    }

    printf("目录创建成功！\n");

    // 显示目录信息
    struct stat dir_stat;
    if (stat(dirname, &dir_stat) == 0) {
        display_file_permissions(dir_stat.st_mode);
    }
}

// 显示目录内容
void list_directory(const char* dirname) {
    printf("目录内容: %s\n", dirname);
    printf("========================================\n");

    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        perror("打开目录失败");
        return;
    }

    struct dirent* entry;
    struct stat file_stat;
    char full_path[MAX_PATH];

    printf("%-20s %-10s %-15s\n", "文件名", "类型", "大小(字节)");
    printf("----------------------------------------\n");

    while ((entry = readdir(dir)) != NULL) {
        // 跳过 . 和 ..
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // 构建完整路径
        snprintf(full_path, sizeof(full_path), "%s/%s", dirname, entry->d_name);

        if (stat(full_path, &file_stat) == 0) {
            const char* type = S_ISDIR(file_stat.st_mode) ? "目录" : 
                              S_ISREG(file_stat.st_mode) ? "文件" : "其他";

            printf("%-20s %-10s %-15ld\n", 
                   entry->d_name, type, file_stat.st_size);
        }
    }

    closedir(dir);
    printf("========================================\n");
}

// 重命名文件
void rename_file(const char* oldname, const char* newname) {
    printf("重命名: %s -> %s\n", oldname, newname);

    if (rename(oldname, newname) == -1) {
        perror("重命名失败");
        return;
    }

    printf("重命名成功！\n");
}

// 复制文件
void copy_file(const char* source, const char* destination) {
    printf("复制文件: %s -> %s\n", source, destination);

    int src_fd = open(source, O_RDONLY);
    if (src_fd == -1) {
        perror("打开源文件失败");
        return;
    }

    int dst_fd = open(destination, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dst_fd == -1) {
        perror("创建目标文件失败");
        close(src_fd);
        return;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read, bytes_written;
    off_t total_bytes = 0;

    while ((bytes_read = read(src_fd, buffer, BUFFER_SIZE)) > 0) {
        bytes_written = write(dst_fd, buffer, bytes_read);
        if (bytes_written != bytes_read) {
            perror("写入目标文件失败");
            break;
        }
        total_bytes += bytes_written;
    }

    close(src_fd);
    close(dst_fd);

    printf("文件复制成功！总共复制 %ld 字节\n", total_bytes);
}

// 显示当前工作目录
void show_current_directory() {
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) != NULL) {
        printf("当前工作目录: %s\n", cwd);
    } else {
        perror("获取当前目录失败");
    }
}

// 演示所有文件操作
void demonstrate_file_operations() {
    printf("\n开始演示文件系统操作...\n");
    printf("========================================\n");

    const char* test_file = "test_file.txt";
    const char* test_dir = "test_directory";
    const char* copied_file = "copied_file.txt";
