// 定义计算数组数值总和的函数
function calculateSum(arr) {
    let sum = 0;
    let output = "";

    // 使用for循环遍历数组
    for (let i = 0; i < arr.length; i++) {
        const element = arr[i];

        // 检查元素是否为数字
        if (typeof element === 'number' && !isNaN(element)) {
            // 如果是数字，添加到总和中
            sum += element;
            output += `<div class="message numeric">元素 ${element} 是数字，已添加到总和</div>`;
        } else {
            // 如果不是数字，输出提示信息
            output += `<div class="message non-numeric">"${element}" 不是一个数值，无法进行和计算</div>`;
        }
    }

    return { sum, output };
}

// 测试数组
const testArray = [1, 4, 5, 77, 32, 'javascript', 99];

