```javascript
// 1. 数组反转函数
function reverseArray(arr) {
    const reversed = [];
    for (let i = arr.length - 1; i >= 0; i--) {
        reversed.push(arr[i]);
    }
    return reversed;
}

// 2. 冒泡排序函数（从大到小）
function bubbleSortDescending(arr) {
    const n = arr.length;
    const steps = [];
    const sortedArray = [...arr]; // 创建数组副本

    for (let i = 0; i < n - 1; i++) {
        let swapped = false;
        steps.push(`第 ${i + 1} 轮排序开始`);

        for (let j = 0; j < n - 1 - i; j++) {
            // 记录比较步骤
            steps.push(`比较 ${sortedArray[j]} 和 ${sortedArray[j + 1]}`);

            if (sortedArray[j] < sortedArray[j + 1]) {
                // 交换元素
                [sortedArray[j], sortedArray[j + 1]] = [sortedArray[j + 1], sortedArray[j]];
                swapped = true;
                steps.push(`交换位置: [${[...sortedArray]}]`);
            }
        }

        steps.push(`第 ${i + 1} 轮排序结束: [${[...sortedArray]}]`);

        // 如果没有发生交换，说明数组已经有序
        if (!swapped) {
            steps.push(`数组已完全有序，提前结束排序`);
            break;
        }
    }

    return { sortedArray, steps };
}

// 逐步执行冒泡排序
let currentStep = 0;
let sortSteps = [];
let currentArray = [];

function bubbleSortStepByStep(arr) {
    const n = arr.length;
    let swapped = false;

    if (currentStep === 0) {
        sortSteps = [];
        currentArray = [...arr];
    }

    if (currentStep < n - 1) {
        for (let j = 0; j < n - 1 - currentStep; j++) {
            sortSteps.push(`比较 ${currentArray[j]} 和 ${currentArray[j + 1]}`);

            if (currentArray[j] < currentArray[j + 1]) {
                [currentArray[j], currentArray[j + 1]] = [currentArray[j + 1], currentArray[j]];
                swapped = true;
                sortSteps.push(`交换位置: [${[...currentArray]}]`);
                break; // 一次只执行一次交换
            }
        }

        if (!swapped && j === n - 1 - currentStep - 1) {
            currentStep++;
        }
    }

    return currentArray;
}

// 页面加载完成后执行
document.addEventListener('DOMContentLoaded', function() {
    // 数组反转部分
    const reverseBtn = document.getElementById('reverseBtn');
    const resetReverseBtn = document.getElementById('resetReverseBtn');
    const reversedResult = document.getElementById('reversedResult');

    const originalArray1 = ['red', 'green', 'blue', 'pink', 'purple'];

    reverseBtn.addEventListener('click', function() {
        const result = reverseArray(originalArray1);
        reversedResult.textContent = JSON.stringify(result);
    });

    resetReverseBtn.addEventListener('click', function() {
        reversedResult.textContent = '';
    });

    // 冒泡排序部分
    const bubbleSortBtn = document.getElementById('bubbleSortBtn');
    const stepBtn = document.getElementById('stepBtn');
    const resetSortBtn = document.getElementById('resetSortBtn');
    const sortProcess = document.getElementById('sortProcess');
    const sortedResult = document.getElementById('sortedResult');

    const originalArray2 = [2, 143, 43, 6456, 678, 43, 3, 232, 298];

    bubbleSortBtn.addEventListener('click', function() {
        const result = bubbleSortDescending(originalArray2);
        sortProcess.innerHTML = '';

        result.steps.forEach(step => {
            const stepElement = document.createElement('div');
            stepElement.className = 'step';
            stepElement.textContent = step;
            sortProcess.appendChild(stepElement);
        });

        sortedResult.textContent = JSON.stringify(result.sortedArray);
    });

    stepBtn.addEventListener('click', function() {
        if (currentStep === 0) {
            currentArray = [...originalArray2];
            sortSteps = [];
        }

        const result = bubbleSortStepByStep(originalArray2);

        // 显示当前步骤
        sortProcess.innerHTML = '';
        sortSteps.forEach(step => {
            const stepElement = document.createElement('div');
            stepElement.className = 'step';
            stepElement.textContent = step;
            sortProcess.appendChild(stepElement);
        });

        sortedResult.textContent = JSON.stringify(result);
        sortSteps = []; // 清空步骤记录

        currentStep++;
        if (currentStep >= originalArray2.length - 1) {
            currentStep = 0;
        }
    });

    resetSortBtn.addEventListener('click', function() {
        sortProcess.innerHTML = '';
        sortedResult.textContent = '';
        currentStep = 0;
        sortSteps = [];
    });

    // 自定义数组测试
    const customReverseBtn = document.getElementById('customReverseBtn');
    const customSortBtn = document.getElementById('customSortBtn');
    const customArrayInput = document.getElementById('customArrayInput');
    const customResult = document.getElementById('customResult');

    customReverseBtn.addEventListener('click', function() {
        const input = customArrayInput.value;
        if (!input) {
            customResult.textContent = '请输入数组元素！';
            return;
        }

        try {
            const customArray = input.split(',').map(item => {
                const trimmed = item.trim();
                // 尝试转换为数字，如果失败则保持字符串
                return isNaN(trimmed) ? trimmed : Number(trimmed);
            });

            const result = reverseArray(customArray);
            customResult.textContent = `反转结果: ${JSON.stringify(result)}`;
        } catch (error) {
            customResult.textContent = '输入格式不正确！';
        }
    });

    customSortBtn.addEventListener('click', function() {
        const input = customArrayInput.value;
        if (!input) {
            customResult.textContent = '请输入数组元素！';
            return;
        }

        try {
            const customArray = input.split(',').map(item => {
                const trimmed = item.trim();
                const num = Number(trimmed);
                if (isNaN(num)) {
                    throw new Error('排序只能对数字数组进行');
                }
                return num;
            });

            const result = bubbleSortDescending(customArray);
            customResult.textContent = `排序结果: ${JSON.stringify(result.sortedArray)}`;
        } catch (error) {
            customResult.textContent = error.message || '输入格式不正确！';
        }
    });
});
