        // 如果没有参数，使用默认值
        String name = (args.length > 0) ? args[0] : "World";
        String language = (args.length > 1) ? args[1] : "en";

        switch (language) {
            case "zh":
                System.out.println("你好，" + name + "！");
                break;
            case "es":
                System.out.println("¡Hola, " + name + "!");
