```java
package com.pomodoro.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.pomodoro.common.Result;
import com.pomodoro.dto.request.TaskCreateRequest;
import com.pomodoro.dto.request.TaskUpdateRequest;
import com.pomodoro.entity.Task;
import com.pomodoro.enums.TaskStatus;
import com.pomodoro.mapper.TaskMapper;
import com.pomodoro.service.TaskService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;

@Service
@RequiredArgsConstructor
public class TaskServiceImpl implements TaskService {

    private final TaskMapper taskMapper;

    @Override
    public Result<Object> createTask(Long userId, TaskCreateRequest request) {
        Task task = new Task();
        task.setUserId(userId);
        task.setTitle(request.getTitle());
        task.setDescription(request.getDescription());
        task.setPriority(request.getPriority() != null ? request.getPriority() : 1);
        task.setStatus(TaskStatus.PENDING.getCode());
        task.setPomodoroCount(0);
        task.setEstimatedPomodoros(request.getEstimatedPomodoros() != null ? request.getEstimatedPomodoros() : 1);
        task.setDeadline(request.getDeadline());

        taskMapper.insert(task);
        return Result.success("创建成功");
    }

    @Override
    public Result<Page<Task>> getTaskList(Long userId, Integer page, Integer size, Integer status) {
        LambdaQueryWrapper<Task> wrapper = new LambdaQueryWrapper<>();
        wrapper.eq(Task::getUserId, userId)
               .eq(status != null, Task::getStatus, status)
               .orderByDesc(Task::getPriority)
               .orderByAsc(Task::getStatus)
               .orderByDesc(Task::getCreatedAt);

        Page<Task> taskPage = taskMapper.selectPage(new Page<>(page, size), wrapper);
        return Result.success(taskPage);
    }

    @Override
    public Result<Task> getTaskDetail(Long taskId, Long userId) {
        Task task = taskMapper.selectById(taskId);
        if (task == null || !task.getUserId().equals(userId)) {
            return Result.error("任务不存在");
        }
        return Result.success(task);
    }

    @Override
    public Result<Object> updateTask(Long userId, TaskUpdateRequest request) {
        Task task = taskMapper.selectById(request.getId());
        if (task == null || !task.getUserId().equals(userId)) {
            return Result.error("任务不存在");
        }

        task.setTitle(request.getTitle());
        task.setDescription(request.getDescription());
        task.setPriority(request.getPriority());
        task.setStatus(request.getStatus());
        task.setEstimatedPomodoros(request.getEstimatedPomodoros());
        task.setDeadline(request.getDeadline());

        taskMapper.updateById(task);
        return Result.success("更新成功");
    }

    @Override
    public Result<Object> deleteTask(Long taskId, Long userId) {
        Task task = taskMapper.selectById(taskId);
        if (task == null || !task.getUserId().equals(userId)) {
            return Result.error("任务不存在");
        }

        taskMapper.deleteById(taskId);
        return Result.success("删除成功");
    }

    @Override
    public Result<Object> completeTask(Long taskId, Long userId) {
        Task task = taskMapper.selectById(taskId);
        if (task == null || !task.getUserId().equals(userId)) {
            return Result.error("任务不存在");
        }

        task.setStatus(TaskStatus.COMPLETED.getCode());
        task.setCompletedAt(LocalDateTime.now());
        taskMapper.updateById(task);
        return Result.success("任务已完成");
    }
