package com.pomodoro.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.pomodoro.common.Result;
import com.pomodoro.dto.request.PomodoroStartRequest;
import com.pomodoro.entity.PomodoroRecord;
import com.pomodoro.entity.Task;
import com.pomodoro.entity.User;
import com.pomodoro.enums.PomodoroStatus;
import com.pomodoro.enums.TaskStatus;
import com.pomodoro.mapper.PomodoroRecordMapper;
import com.pomodoro.mapper.TaskMapper;
import com.pomodoro.mapper.UserMapper;
import com.pomodoro.service.PomodoroService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;

@Service
@RequiredArgsConstructor
public class PomodoroServiceImpl implements PomodoroService {

    private final PomodoroRecordMapper pomodoroRecordMapper;
    private final TaskMapper taskMapper;
    private final UserMapper userMapper;

    @Override
    @Transactional
    public Result<PomodoroRecord> startPomodoro(Long userId, PomodoroStartRequest request) {
        LambdaQueryWrapper<PomodoroRecord> wrapper = new LambdaQueryWrapper<>();
        wrapper.eq(PomodoroRecord::getUserId, userId)
               .eq(PomodoroRecord::getStatus, PomodoroStatus.IN_PROGRESS.getCode());
        if (pomodoroRecordMapper.selectCount(wrapper) > 0) {
            return Result.error("请先完成当前番茄钟");
        }

        PomodoroRecord record = new PomodoroRecord();
        record.setUserId(userId);
        record.setTaskId(request.getTaskId());
        record.setDuration(request.getDuration());
        record.setStatus(PomodoroStatus.IN_PROGRESS.getCode());
        record.setStartTime(LocalDateTime.now());

        pomodoroRecordMapper.insert(record);

        if (request.getTaskId() != null) {
            Task task = taskMapper.selectById(request.getTaskId());
            if (task != null && task.getStatus().equals(TaskStatus.PENDING.getCode())) {
                task.setStatus(TaskStatus.IN_PROGRESS.getCode());
                taskMapper.updateById(task);
            }
        }

        return Result.success(record);
    }

    @Override
    public Result<Object> pausePomodoro(Long recordId, Long userId) {
        PomodoroRecord record = pomodoroRecordMapper.selectById(recordId);
        if (record == null || !record.getUserId().equals(userId)) {
            return Result.error("记录不存在");
        }
        if (!record.getStatus().equals(PomodoroStatus.IN_PROGRESS.getCode())) {
            return Result.error("当前番茄钟未在进行中");
        }

        // 暂不支持暂停功能，前端可自行处理计时器暂停
        return Result.error("暂不支持暂停，可直接放弃");
    }

    @Override
    public Result<Object> resumePomodoro(Long recordId, Long userId) {
        return Result.error("暂不支持恢复功能");
    }

    @Override
    @Transactional
    public Result<Object> completePomodoro(Long recordId, Long userId) {
        PomodoroRecord record = pomodoroRecordMapper.selectById(recordId);
        if (record == null || !record.getUserId().equals(userId)) {
            return Result.error("记录不存在");
        }
        if (!record.getStatus().equals(PomodoroStatus.IN_PROGRESS.getCode())) {
            return Result.error("当前番茄钟未在进行中");
        }

        record.setStatus(PomodoroStatus.COMPLETED.getCode());
        record.setEndTime(LocalDateTime.now());
        pomodoroRecordMapper.updateById(record);

        if (record.getTaskId() != null) {
            Task task = taskMapper.selectById(record.getTaskId());
            task.setPomodoroCount(task.getPomodoroCount() + 1);
            taskMapper.updateById(task);
        }

        User user = userMapper.selectById(userId);
        user.setTotalFocusTime(user.getTotalFocusTime() + record.getDuration());
        userMapper.updateById(user);

        return Result.success("专注完成");
    }

    @Override
    @Transactional
    public Result<Object> cancelPomodoro(Long recordId, Long userId) {
        PomodoroRecord record = pomodoroRecordMapper.selectById(recordId);
        if (record == null || !record.getUserId().equals(userId)) {
            return Result.error("记录不存在");
        }

        record.setStatus(PomodoroStatus.CANCELLED.getCode());
        record.setEndTime(LocalDateTime.now());
        pomodoroRecordMapper.updateById(record);

        if (record.getTaskId() != null) {
            Task task = taskMapper.selectById(record.getTaskId());
            if (task.getStatus().equals(TaskStatus.IN_PROGRESS.getCode())) {
                task.setStatus(TaskStatus.PENDING.getCode());
                taskMapper.updateById(task);
            }
        }

        return Result.success("已放弃本次专注");
    }

    @Override
    public Result<List<PomodoroRecord>> getTodayRecords(Long userId) {
        LocalDate today = LocalDate.now();
        LambdaQueryWrapper<PomodoroRecord> wrapper = new LambdaQueryWrapper<>();
        wrapper.eq(PomodoroRecord::getUserId, userId)
               .ge(PomodoroRecord::getStartTime, today.atStartOfDay())
               .lt(PomodoroRecord::getStartTime, today.plusDays(1).atStartOfDay())
               .orderByDesc(PomodoroRecord::getStartTime);

        List<PomodoroRecord> records = pomodoroRecordMapper.selectList(wrapper);
        return Result.success(records);
    }

    @Override
    public Result<Page<PomodoroRecord>> getHistoryRecords(Long userId, Integer page, Integer size) {
        LambdaQueryWrapper<PomodoroRecord> wrapper = new LambdaQueryWrapper<>();
        wrapper.eq(PomodoroRecord::getUserId, userId)
               .orderByDesc(PomodoroRecord::getStartTime);

        Page<PomodoroRecord> recordPage = pomodoroRecordMapper.selectPage(new Page<>(page, size), wrapper);
        return Result.success(recordPage);
    }
}
