package com.pomodoro.service.impl;

import com.pomodoro.common.Result;
import com.pomodoro.entity.FocusHistory;
import com.pomodoro.entity.Task;
import com.pomodoro.enums.TaskStatus;
import com.pomodoro.mapper.FocusHistoryMapper;
import com.pomodoro.mapper.PomodoroRecordMapper;
import com.pomodoro.mapper.TaskMapper;
import com.pomodoro.service.StatisticsService;
import com.pomodoro.vo.StatisticsVO;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

@Service
@RequiredArgsConstructor
public class StatisticsServiceImpl implements StatisticsService {

    private final PomodoroRecordMapper pomodoroRecordMapper;
    private final TaskMapper taskMapper;
    private final FocusHistoryMapper focusHistoryMapper;

    @Override
    public Result<StatisticsVO.TodayStatistics> getTodayStatistics(Long userId) {
        LocalDate today = LocalDate.now();
        int completedPomodoros = pomodoroRecordMapper.countCompletedByDate(userId, today);

        StatisticsVO.TodayStatistics stats = new StatisticsVO.TodayStatistics();
        stats.setCompletedPomodoros(completedPomodoros);
        stats.setTotalFocusMinutes(completedPomodoros * 25);

        return Result.success(stats);
    }

    @Override
    public Result<StatisticsVO.WeekStatistics> getWeekStatistics(Long userId) {
        LocalDate today = LocalDate.now();
        LocalDate startOfWeek = today.minusDays(today.getDayOfWeek().getValue() - 1);
        LocalDate endOfWeek = startOfWeek.plusDays(6);

        List<FocusHistory> histories = focusHistoryMapper.selectByDateRange(userId, startOfWeek, endOfWeek);

        List<StatisticsVO.DailyStatistics> dailyList = new ArrayList<>();
        for (int i = 0; i < 7; i++) {
            LocalDate date = startOfWeek.plusDays(i);
            String dateStr = date.format(DateTimeFormatter.ofPattern("MM-dd"));

            int minutes = histories.stream()
                    .filter(h -> h.getDate().equals(date))
                    .mapToInt(FocusHistory::getTotalMinutes)
                    .findFirst()
                    .orElse(0);

            dailyList.add(new StatisticsVO.DailyStatistics(dateStr, minutes));
        }

        StatisticsVO.WeekStatistics stats = new StatisticsVO.WeekStatistics();
        stats.setWeekStart(startOfWeek.format(DateTimeFormatter.ofPattern("yyyy-MM-dd")));
        stats.setWeekEnd(endOfWeek.format(DateTimeFormatter.ofPattern("yyyy-MM-dd")));
        stats.setDailyData(dailyList);

        return Result.success(stats);
    }

    @Override
    public Result<StatisticsVO.MonthStatistics> getMonthStatistics(Long userId) {
        LocalDate today = LocalDate.now();
        LocalDate startOfMonth = today.withDayOfMonth(1);
        LocalDate endOfMonth = today.withDayOfMonth(today.lengthOfMonth());

        List<FocusHistory> histories = focusHistoryMapper.selectByDateRange(userId, startOfMonth, endOfMonth);

        List<StatisticsVO.DailyStatistics> dailyList = new ArrayList<>();
        for (int i = 0; i < today.lengthOfMonth(); i++) {
            LocalDate date = startOfMonth.plusDays(i);
            String dateStr = date.format(DateTimeFormatter.ofPattern("MM-dd"));

            int minutes = histories.stream()
                    .filter(h -> h.getDate().equals(date))
                    .mapToInt(FocusHistory::getTotalMinutes)
                    .findFirst()
                    .orElse(0);

            dailyList.add(new StatisticsVO.DailyStatistics(dateStr, minutes));
        }

        int totalMinutes = histories.stream().mapToInt(FocusHistory::getTotalMinutes).sum();

        StatisticsVO.MonthStatistics stats = new StatisticsVO.MonthStatistics();
        stats.setMonth(today.format(DateTimeFormatter.ofPattern("yyyy年MM月")));
        stats.setTotalFocusMinutes(totalMinutes);
        stats.setDailyData(dailyList);

        return Result.success(stats);
    }
}
