package com.pomodoro.mapper;

import com.pomodoro.BaseTest;
import com.pomodoro.entity.User;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.beans.factory.annotation.Autowired;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

@DisplayName("用户Mapper测试")
class UserMapperTest extends BaseTest {

    @Autowired
    private UserMapper userMapper;

    @Nested
    @DisplayName("插入操作测试")
    class InsertTests {

        @Test
        @DisplayName("插入用户成功")
        void testInsertUser() {
            User user = createUser("testuser", "test@example.com");

            int result = userMapper.insert(user);

            assertThat(result).isEqualTo(1);
            assertThat(user.getId()).isNotNull();
            assertThat(user.getCreatedAt()).isNotNull();
        }

        @Test
        @DisplayName("插入重复用户名应抛出异常")
        void testInsertDuplicateUsername() {
            User user1 = createUser("duplicate", "email1@test.com");
            User user2 = createUser("duplicate", "email2@test.com");
            userMapper.insert(user1);

            org.junit.jupiter.api.Assertions.assertThrows(
                org.springframework.dao.DuplicateKeyException.class,
                () -> userMapper.insert(user2)
            );
        }
    }

    @Nested
    @DisplayName("查询操作测试")
    class QueryTests {

        @Test
        @DisplayName("根据ID查询用户")
        void testSelectById() {
            User user = createUser("selectbyid", "select@test.com");
            userMapper.insert(user);

            User found = userMapper.selectById(user.getId());

            assertThat(found).isNotNull();
            assertThat(found.getUsername()).isEqualTo("selectbyid");
            assertThat(found.getEmail()).isEqualTo("select@test.com");
        }

        @Test
        @DisplayName("根据用户名查询用户")
        void testSelectByUsername() {
            User user = createUser("uniquename", "unique@test.com");
            userMapper.insert(user);

            User found = userMapper.selectOne(
                new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<User>()
                    .eq(User::getUsername, "uniquename")
            );

            assertThat(found).isNotNull();
            assertThat(found.getUsername()).isEqualTo("uniquename");
        }

        @ParameterizedTest
        @ValueSource(strings = {"user1", "user2", "user3"})
        @DisplayName("参数化测试：查询多个用户")
        void testSelectMultipleUsers(String username) {
            User user = createUser(username, username + "@test.com");
            userMapper.insert(user);

            User found = userMapper.selectById(user.getId());

            assertThat(found).isNotNull();
            assertThat(found.getUsername()).isEqualTo(username);
        }
    }

    @Nested
    @DisplayName("更新操作测试")
    class UpdateTests {

        @Test
        @DisplayName("更新用户信息")
        void testUpdateUser() {
            User user = createUser("updateuser", "old@test.com");
            userMapper.insert(user);

            user.setNickname("新昵称");
            user.setEmail("new@test.com");
            int result = userMapper.updateById(user);

            assertThat(result).isEqualTo(1);

            User updated = userMapper.selectById(user.getId());
            assertThat(updated.getNickname()).isEqualTo("新昵称");
            assertThat(updated.getEmail()).isEqualTo("new@test.com");
        }

        @Test
        @DisplayName("更新累计专注时长")
        void testUpdateTotalFocusTime() {
            User user = createUser("focususer", "focus@test.com");
            userMapper.insert(user);

            user.setTotalFocusTime(100);
            userMapper.updateById(user);

            User updated = userMapper.selectById(user.getId());
            assertThat(updated.getTotalFocusTime()).isEqualTo(100);
        }
    }

    @Nested
    @DisplayName("删除操作测试")
    class DeleteTests {

        @Test
        @DisplayName("逻辑删除用户")
        void testLogicDelete() {
            User user = createUser("deleteuser", "delete@test.com");
            userMapper.insert(user);

            int result = userMapper.deleteById(user.getId());

            assertThat(result).isEqualTo(1);

            User deleted = userMapper.selectById(user.getId());
            assertThat(deleted).isNull();
        }
    }

    private User createUser(String username, String email) {
        User user = new User();
        user.setUsername(username);
        user.setPassword("encryptedPassword");
        user.setNickname(username);
        user.setEmail(email);
        user.setTotalFocusTime(0);
        user.setConsecutiveDays(0);
        return user;
    }
}
