package com.pomodoro.mapper;

import com.pomodoro.BaseTest;
import com.pomodoro.entity.Task;
import com.pomodoro.entity.User;
import com.pomodoro.enums.TaskPriority;
import com.pomodoro.enums.TaskStatus;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

@DisplayName("任务Mapper测试")
class TaskMapperTest extends BaseTest {

    @Autowired
    private TaskMapper taskMapper;

    @Autowired
    private UserMapper userMapper;

    private Long testUserId;

    @BeforeEach
    void setUp() {
        User user = new User();
        user.setUsername("taskmapperuser");
        user.setPassword("password");
        userMapper.insert(user);
        testUserId = user.getId();
    }

    @Nested
    @DisplayName("插入操作测试")
    class InsertTests {

        @Test
        @DisplayName("插入任务成功")
        void testInsertTask() {
            Task task = createTask("测试任务", TaskPriority.MEDIUM.getCode());

            int result = taskMapper.insert(task);

            assertThat(result).isEqualTo(1);
            assertThat(task.getId()).isNotNull();
        }

        @Test
        @DisplayName("插入高优先级任务")
        void testInsertHighPriorityTask() {
            Task task = createTask("紧急任务", TaskPriority.HIGH.getCode());
            taskMapper.insert(task);

            assertThat(task.getPriority()).isEqualTo(TaskPriority.HIGH.getCode());
        }
    }

    @Nested
    @DisplayName("查询操作测试")
    class QueryTests {

        @Test
        @DisplayName("查询待处理任务列表")
        void testSelectPendingTasks() {
            for (int i = 0; i < 3; i++) {
                Task task = createTask("待处理任务" + i, TaskPriority.LOW.getCode());
                task.setStatus(TaskStatus.PENDING.getCode());
                taskMapper.insert(task);
            }

            List<Task> pendingTasks = taskMapper.selectPendingTasks(testUserId);

            assertThat(pendingTasks).hasSize(3);
            assertThat(pendingTasks).allMatch(t -> t.getStatus().equals(TaskStatus.PENDING.getCode()));
        }

        @Test
        @DisplayName("按优先级排序查询")
        void testSelectOrderByPriority() {
            Task taskLow = createTask("低优先级", TaskPriority.LOW.getCode());
            Task taskHigh = createTask("高优先级", TaskPriority.HIGH.getCode());
            Task taskMedium = createTask("中优先级", TaskPriority.MEDIUM.getCode());
            taskMapper.insert(taskLow);
            taskMapper.insert(taskHigh);
            taskMapper.insert(taskMedium);

            List<Task> tasks = taskMapper.selectPendingTasks(testUserId);

            assertThat(tasks).isNotEmpty();
            assertThat(tasks.get(0).getPriority()).isGreaterThanOrEqualTo(tasks.get(1).getPriority());
        }
    }

    @Nested
    @DisplayName("更新操作测试")
    class UpdateTests {

        @Test
        @DisplayName("完成任务")
        void testCompleteTask() {
            Task task = createTask("待完成任务", TaskPriority.MEDIUM.getCode());
            task.setStatus(TaskStatus.PENDING.getCode());
            taskMapper.insert(task);

            int result = taskMapper.completeTask(task.getId());

            assertThat(result).isEqualTo(1);

            Task completed = taskMapper.selectById(task.getId());
            assertThat(completed.getStatus()).isEqualTo(TaskStatus.COMPLETED.getCode());
            assertThat(completed.getCompletedAt()).isNotNull();
        }

        @Test
        @DisplayName("更新任务状态为进行中")
        void testUpdateTaskStatus() {
            Task task = createTask("进行中任务", TaskPriority.MEDIUM.getCode());
            task.setStatus(TaskStatus.PENDING.getCode());
            taskMapper.insert(task);

            task.setStatus(TaskStatus.IN_PROGRESS.getCode());
            taskMapper.updateById(task);

            Task updated = taskMapper.selectById(task.getId());
            assertThat(updated.getStatus()).isEqualTo(TaskStatus.IN_PROGRESS.getCode());
        }

        @Test
        @DisplayName("增加番茄钟计数")
        void testIncrementPomodoroCount() {
            Task task = createTask("计数任务", TaskPriority.LOW.getCode());
            task.setPomodoroCount(0);
            taskMapper.insert(task);

            task.setPomodoroCount(task.getPomodoroCount() + 1);
            taskMapper.updateById(task);

            Task updated = taskMapper.selectById(task.getId());
            assertThat(updated.getPomodoroCount()).isEqualTo(1);
        }
    }

    private Task createTask(String title, int priority) {
        Task task = new Task();
        task.setUserId(testUserId);
        task.setTitle(title);
        task.setDescription(title + "的描述");
        task.setPriority(priority);
        task.setStatus(TaskStatus.PENDING.getCode());
        task.setPomodoroCount(0);
        task.setEstimatedPomodoros(1);
        return task;
    }
}
