    @Nested
    @DisplayName("用户注册测试")
    class RegisterTests {

        @Test
        @DisplayName("注册成功")
        void testRegisterSuccess() {
            RegisterRequest request = createRegisterRequest("newuser", "password123", "newuser@example.com");

            Result<Object> result = userService.register(request);

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getMessage()).isEqualTo("注册成功");
        }

        @Test
        @DisplayName("注册重复用户名应失败")
        void testRegisterDuplicateUsername() {
            RegisterRequest request1 = createRegisterRequest("duplicate", "pass1", "email1@test.com");
            userService.register(request1);

            RegisterRequest request2 = createRegisterRequest("duplicate", "pass2", "email2@test.com");
            Result<Object> result = userService.register(request2);

            assertThat(result.getCode()).isEqualTo(500);
            assertThat(result.getMessage()).isEqualTo("用户名已存在");
        }

        @ParameterizedTest
        @CsvSource({
            "ab, password123, 用户名长度4-20位",
            "verylongusername12345678901, password123, 用户名长度4-20位",
            "validuser, 123, 密码长度6-20位"
        })
