            userService.register(registerRequest);

            LoginRequest loginRequest = new LoginRequest();
            loginRequest.setUsername("loginuser");
            loginRequest.setPassword("loginpass");

            Result<LoginResponse> result = userService.login(loginRequest);

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getData()).isNotNull();
            assertThat(result.getData().getUsername()).isEqualTo("loginuser");
            assertThat(result.getData().getToken()).isNotNull();
            assertThat(result.getData().getToken()).isNotEmpty();
        }

        @Test
        @DisplayName("密码错误登录失败")
        void testLoginWrongPassword() {
            RegisterRequest registerRequest = createRegisterRequest("wrongpass", "correctpass", "wrong@test.com");
            userService.register(registerRequest);

            LoginRequest loginRequest = new LoginRequest();
            loginRequest.setUsername("wrongpass");
            loginRequest.setPassword("wrongpass");

            Result<LoginResponse> result = userService.login(loginRequest);

            assertThat(result.getCode()).isEqualTo(500);
