            userService.register(registerRequest);

            LoginRequest loginRequest = new LoginRequest();
            loginRequest.setUsername("infouser");
            loginRequest.setPassword("password");
            Result<LoginResponse> loginResult = userService.login(loginRequest);
            Long userId = loginResult.getData().getUserId();

            Result<UserInfoResponse> result = userService.getUserInfo(userId);

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getData().getUsername()).isEqualTo("infouser");
            assertThat(result.getData().getEmail()).isEqualTo("info@test.com");
        }

        @Test
        @DisplayName("更新用户信息成功")
        void testUpdateUserInfo() {
            RegisterRequest registerRequest = createRegisterRequest("updateuser", "password", "old@test.com");
            userService.register(registerRequest);

            LoginRequest loginRequest = new LoginRequest();
            loginRequest.setUsername("updateuser");
            loginRequest.setPassword("password");
            Result<LoginResponse> loginResult = userService.login(loginRequest);
            Long userId = loginResult.getData().getUserId();

            Result<Object> result = userService.updateUserInfo(userId, "新昵称", "new@test.com", "new_avatar.jpg");

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getMessage()).isEqualTo("更新成功");

            Result<UserInfoResponse> updated = userService.getUserInfo(userId);
            assertThat(updated.getData().getNickname()).isEqualTo("新昵称");
            assertThat(updated.getData().getEmail()).isEqualTo("new@test.com");
        }
    }

    private RegisterRequest createRegisterRequest(String username, String password, String email) {
        RegisterRequest request = new RegisterRequest();
        request.setUsername(username);
        request.setPassword(password);
        request.setEmail(email);
        request.setNickname(username);
        return request;
    }
}
