            TaskCreateRequest request = createTaskRequest("待完成任务", null, 1, 1);
            taskService.createTask(testUserId, request);

            Result<Page<Task>> listResult = taskService.getTaskList(testUserId, 1, 10, null);
            Long taskId = listResult.getData().getRecords().get(0).getId();

            Result<Object> result = taskService.completeTask(taskId, testUserId);

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getMessage()).isEqualTo("任务已完成");

            Result<Task> detailResult = taskService.getTaskDetail(taskId, testUserId);
            assertThat(detailResult.getData().getStatus()).isEqualTo(2);
            assertThat(detailResult.getData().getCompletedAt()).isNotNull();
        }
    }

    @Nested
    @DisplayName("任务删除测试")
