            Result<Page<Task>> listResult = taskService.getTaskList(testUserId, 1, 10, null);
            Long taskId = listResult.getData().getRecords().get(0).getId();

            Result<Object> result = taskService.deleteTask(taskId, testUserId);

            assertThat(result.getCode()).isEqualTo(200);
            assertThat(result.getMessage()).isEqualTo("删除成功");

            Result<Task> detailResult = taskService.getTaskDetail(taskId, testUserId);
            assertThat(detailResult.getCode()).isEqualTo(500);
            assertThat(detailResult.getMessage()).isEqualTo("任务不存在");
        }
    }

    private TaskCreateRequest createTaskRequest(String title, String description, int priority, int estimated) {
        TaskCreateRequest request = new TaskCreateRequest();
        request.setTitle(title);
        request.setDescription(description);
        request.setPriority(priority);
        request.setEstimatedPomodoros(estimated);
        return request;
    }
}
