## 七、工具类测试（JUnit 5）

### JwtUtilTest.java

```java
package com.pomodoro.utils;

import com.pomodoro.BaseTest;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.springframework.beans.factory.annotation.Autowired;
import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

@DisplayName("JWT工具测试")
class JwtUtilTest extends BaseTest {

    @Autowired
    private JwtUtil jwtUtil;

    @Nested
    @DisplayName("Token生成测试")
    class GenerateTests {

        @Test
        @DisplayName("生成Token成功")
        void testGenerateToken() {
            String token = jwtUtil.generateToken(1L, "testuser");

            assertThat(token).isNotNull();
            assertThat(token).isNotEmpty();
            assertThat(token.split("\\.")).hasSize(3);
        }

        @ParameterizedTest
        @CsvSource({
            "1, user1",
            "100, user100",
            "999, user999"
        })
        @DisplayName("参数化测试：生成多个用户的Token")
        void testGenerateTokenForMultipleUsers(Long userId, String username) {
            String token = jwtUtil.generateToken(userId, username);

            assertThat(token).isNotNull();
            assertThat(jwtUtil.getUserIdFromToken(token)).isEqualTo(userId);
            assertThat(jwtUtil.getUsernameFromToken(token)).isEqualTo(username);
        }
    }

    @Nested
    @DisplayName("Token解析测试")
    class ParseTests {

        @Test
        @DisplayName("从Token获取用户ID")
        void testGetUserIdFromToken() {
            Long expectedUserId = 123L;
            String token = jwtUtil.generateToken(expectedUserId, "user123");

            Long userId = jwtUtil.getUserIdFromToken(token);

            assertThat(userId).isEqualTo(expectedUserId);
        }

        @Test
        @DisplayName("从Token获取用户名")
        void testGetUsernameFromToken() {
            String expectedUsername = "testusername";
            String token = jwtUtil.generateToken(1L, expectedUsername);

            String username = jwtUtil.getUsernameFromToken(token);

            assertThat(username).isEqualTo(expectedUsername);
        }
    }

    @Nested
    @DisplayName("Token验证测试")
    class ValidateTests {

        @Test
        @DisplayName("有效Token验证通过")
        void testValidateTokenValid() {
            String token = jwtUtil.generateToken(1L, "validuser");

            boolean isValid = jwtUtil.validateToken(token);

            assertThat(isValid).isTrue();
        }

        @Test
        @DisplayName("无效Token验证失败")
        void testValidateTokenInvalid() {
            boolean isValid = jwtUtil.validateToken("invalid.token.string");

            assertThat(isValid).isFalse();
        }

        @Test
        @DisplayName("空Token验证失败")
        void testValidateTokenEmpty() {
            boolean isValid = jwtUtil.validateToken("");

            assertThat(isValid).isFalse();
        }

        @Test
        @DisplayName("null Token验证失败")
        void testValidateTokenNull() {
            boolean isValid = jwtUtil.validateToken(null);

            assertThat(isValid).isFalse();
        }
    }
}
