### 5.2 stores/pomodoro.js

```javascript
import { defineStore } from 'pinia'
import { startPomodoro, completePomodoro, cancelPomodoro, getTodayRecords } from '@/api/pomodoro'
import { ElNotification } from 'element-plus'

export const usePomodoroStore = defineStore('pomodoro', {
  state: () => ({
    currentRecord: null,
    isRunning: false,
    remainingSeconds: 25 * 60, // 25分钟 = 1500秒
    timer: null,
    currentMode: 'work', // work, rest
    workDuration: 25 * 60,
    restDuration: 5 * 60,
    longRestDuration: 15 * 60,
    pomodoroCount: 0,
    todayRecords: []
  }),

  getters: {
    formattedRemainingTime: (state) => {
      const minutes = Math.floor(state.remainingSeconds / 60)
      const seconds = state.remainingSeconds % 60
      return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
    },
    progress: (state) => {
      const total = state.currentMode === 'work' ? state.workDuration : state.restDuration
      return ((total - state.remainingSeconds) / total) * 100
    }
  },

  actions: {
    // 开始专注
    async start(taskId, duration = 25) {
      try {
        const res = await startPomodoro({ taskId, duration })
        if (res.code === 200) {
          this.currentRecord = res.data
          this.isRunning = true
          this.remainingSeconds = duration * 60
          this.startTimer()
          return { success: true }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    // 启动计时器
    startTimer() {
      if (this.timer) clearInterval(this.timer)
      this.timer = setInterval(() => {
        if (this.remainingSeconds > 0 && this.isRunning) {
          this.remainingSeconds--
        } else if (this.remainingSeconds === 0 && this.isRunning) {
          this.handleTimeUp()
        }
      }, 1000)
    },

    // 暂停
    pause() {
      this.isRunning = false
    },

    // 恢复
    resume() {
      this.isRunning = true
    },

    // 重置
    reset() {
      this.isRunning = false
      this.remainingSeconds = this.currentMode === 'work' ? this.workDuration : this.restDuration
      if (this.timer) clearInterval(this.timer)
    },

    // 时间到
    async handleTimeUp() {
      this.isRunning = false
      if (this.timer) clearInterval(this.timer)

      if (this.currentMode === 'work') {
        // 完成一个番茄钟
        if (this.currentRecord) {
          await completePomodoro(this.currentRecord.id)
          this.pomodoroCount++
          await this.fetchTodayRecords()
        }

        // 通知
        ElNotification({
          title: '专注完成',
          message: '休息一下吧！',
          type: 'success',
          duration: 5000
        })

        // 切换到休息模式
        this.currentMode = 'rest'
        this.remainingSeconds = (this.pomodoroCount % 4 === 0) ? this.longRestDuration : this.restDuration
        this.currentRecord = null
        this.startTimer()
        this.isRunning = true
      } else {
        // 休息结束
        ElNotification({
          title: '休息结束',
          message: '开始新的专注吧！',
          type: 'info',
          duration: 5000
        })

        this.currentMode = 'work'
        this.remainingSeconds = this.workDuration
      }
    },

    // 放弃当前专注
    async cancel() {
      if (this.currentRecord) {
        await cancelPomodoro(this.currentRecord.id)
      }
      this.reset()
      this.currentRecord = null
      this.currentMode = 'work'
      this.remainingSeconds = this.workDuration
      if (this.timer) clearInterval(this.timer)
    },

    // 获取今日记录
    async fetchTodayRecords() {
      try {
        const res = await getTodayRecords()
        if (res.code === 200) {
          this.todayRecords = res.data
        }
      } catch (error) {
        console.error('获取今日记录失败', error)
      }
    },

    // 清理定时器
    clearTimer() {
      if (this.timer) {
        clearInterval(this.timer)
        this.timer = null
      }
    }
  }
})
