import { ref, computed, onMounted, onUnmounted } from 'vue'
import { VideoPlay, VideoPause, Close } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { usePomodoroStore } from '@/stores/pomodoro'
import { useTaskStore } from '@/stores/task'

const pomodoroStore = usePomodoroStore()
const taskStore = useTaskStore()

const selectedTaskId = ref(null)
const pendingTasks = ref([])

const isRunning = computed(() => pomodoroStore.isRunning)
const currentRecord = computed(() => pomodoroStore.currentRecord)
const remainingSeconds = computed(() => pomodoroStore.remainingSeconds)
const formattedRemainingTime = computed(() => pomodoroStore.formattedRemainingTime)
const progress = computed(() => pomodoroStore.progress)
const pomodoroCount = computed(() => pomodoroStore.pomodoroCount)
const currentMode = computed(() => pomodoroStore.currentMode)

const modeText = computed(() => {
  return currentMode.value === 'work' ? '专注时间' : '休息时间'
})

const progressColor = computed(() => {
  return currentMode.value === 'work' ? '#f5576c' : '#4ade80'
})

const handleStart = async () => {
  const result = await pomodoroStore.start(selectedTaskId.value, 25)
  if (!result.success) {
    ElMessage.error(result.message)
  }
}

const handlePause = () => {
  pomodoroStore.pause()
}

const handleResume = () => {
  pomodoroStore.resume()
}

const handleCancel = async () => {
  await pomodoroStore.cancel()
  ElMessage.info('已放弃本次专注')
}

const loadPendingTasks = async () => {
  const result = await taskStore.fetchTaskList({ status: 0, page: 1, size: 100 })
  if (result.success) {
    pendingTasks.value = result.data.records
  }
}

onMounted(() => {
  loadPendingTasks()
  pomodoroStore.fetchTodayRecords()
})

onUnmounted(() => {
  pomodoroStore.clearTimer()
})
