<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Timer } from '@element-plus/icons-vue'
import { useTaskStore } from '@/stores/task'
import TaskForm from './TaskForm.vue'

const props = defineProps({
  limit: {
    type: Number,
    default: 0
  }
})

const router = useRouter()
const taskStore = useTaskStore()
const tasks = ref([])
const formVisible = ref(false)
const editingTask = ref(null)
const showMore = ref(false)

const loadTasks = async () => {
  const result = await taskStore.fetchTaskList({ status: 0, page: 1, size: props.limit || 100 })
  if (result.success) {
    tasks.value = result.data.records
    if (props.limit > 0 && result.data.total > props.limit) {
      showMore.value = true
    }
  }
}

const handleComplete = async (task) => {
  const result = await taskStore.completeTask(task.id)
  if (result.success) {
    ElMessage.success('任务已完成')
    await loadTasks()
  }
}

const handleEdit = (task) => {
  editingTask.value = task
  formVisible.value = true
}

const handleDelete = async (task) => {
  try {
    await ElMessageBox.confirm('确定要删除这个任务吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    })

    const result = await taskStore.deleteTask(task.id)
    if (result.success) {
      ElMessage.success('删除成功')
      await loadTasks()
    }
  } catch {
    // 取消删除
  }
}

const goToTasks = () => {
  router.push('/tasks')
}

onMounted(() => {
  loadTasks()
})
</script>

