<script setup>
import { ref, reactive, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus } from '@element-plus/icons-vue'
import dayjs from 'dayjs'
import Header from '@/components/common/Header.vue'
import TaskForm from '@/components/task/TaskForm.vue'
import { getTaskList, completeTask, deleteTask } from '@/api/task'

const loading = ref(false)
const tasks = ref([])
const total = ref(0)
const currentPage = ref(1)
const pageSize = ref(10)
const filterStatus = ref(null)
const searchKeyword = ref('')
const formVisible = ref(false)
const editingTask = ref(null)

const statistics = reactive({
  total: 0,
  completed: 0,
  pending: 0,
  expired: 0
})

const formatDate = (date) => {
  return dayjs(date).format('YYYY-MM-DD HH:mm')
}

const loadTasks = async () => {
  loading.value = true
  try {
    const params = {
      page: currentPage.value,
      size: pageSize.value,
      status: filterStatus.value,
      keyword: searchKeyword.value
    }
    const res = await getTaskList(params)
    if (res.code === 200) {
      tasks.value = res.data.records
      total.value = res.data.total

      // 更新统计
      const allTasks = res.data.records
      statistics.total = res.data.total
      statistics.completed = allTasks.filter(t => t.status === 2).length
      statistics.pending = allTasks.filter(t => t.status === 0 || t.status === 1).length
      statistics.expired = allTasks.filter(t => t.status === 3).length
    }
  } catch (error) {
    console.error('加载任务失败', error)
  } finally {
    loading.value = false
  }
}

const handleComplete = async (task) => {
  try {
    await ElMessageBox.confirm('确定要完成任务吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'info'
    })

    const res = await completeTask(task.id)
    if (res.code === 200) {
      ElMessage.success('任务已完成')
      await loadTasks()
    }
  } catch {
    // 取消操作
  }
}

const handleEdit = (task) => {
  editingTask.value = task
  formVisible.value = true
}

const handleDelete = async (task) => {
  try {
    await ElMessageBox.confirm('确定要删除这个任务吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    })

    const res = await deleteTask(task.id)
    if (res.code === 200) {
      ElMessage.success('删除成功')
      await loadTasks()
    }
  } catch {
    // 取消操作
  }
}

const showCreateForm = () => {
  editingTask.value = null
  formVisible.value = true
}

const onFormSuccess = () => {
  formVisible.value = false
  editingTask.value = null
  loadTasks()
}

onMounted(() => {
  loadTasks()
})
</script>

