        </div>
      </div>

      <div class="detail-section">
        <div class="chart-card">
          <h3>每日明细</h3>
          <el-table :data="dailyData" stripe>
            <el-table-column prop="date" label="日期" width="120" />
            <el-table-column prop="minutes" label="专注时长(分钟)" width="150">
              <template #default="{ row }">
                <el-progress :percentage="getPercentage(row.minutes)" :stroke-width="8" />
              </template>
            </el-table-column>
            <el-table-column prop="pomodoros" label="番茄钟数量" width="100" />
            <el-table-column prop="tasks" label="完成任务数" width="100" />
