<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import * as echarts from 'echarts'
import { Timer, Check, List } from '@element-plus/icons-vue'
import Header from '@/components/common/Header.vue'
import { getWeekStatistics, getMonthStatistics } from '@/api/statistics'

const dateRange = ref('week')
const totalFocusMinutes = ref(0)
const totalPomodoros = ref(0)
const totalTasks = ref(0)
const dailyData = ref([])
const trendChartRef = ref(null)
let trendChart = null

const getPercentage = (minutes) => {
  const maxMinutes = Math.max(...dailyData.value.map(d => d.minutes), 60)
  return (minutes / maxMinutes) * 100
}

const loadStatistics = async () => {
  try {
    let res
    if (dateRange.value === 'week') {
      res = await getWeekStatistics()
    } else {
      res = await getMonthStatistics()
    }

    if (res.code === 200) {
      const data = res.data
      totalFocusMinutes.value = data.totalFocusMinutes || 0
      totalPomodoros.value = data.totalPomodoros || 0
      totalTasks.value = data.totalTasks || 0
      dailyData.value = data.dailyData || []

      renderChart()
    }
  } catch (error) {
    console.error('加载统计数据失败', error)
  }
}

const renderChart = () => {
  if (!trendChartRef.value) return

  if (trendChart) {
    trendChart.dispose()
  }

  trendChart = echarts.init(trendChartRef.value)

  const dates = dailyData.value.map(d => d.date)
  const minutes = dailyData.value.map(d => d.minutes)
  const pomodoros = dailyData.value.map(d => d.pomodoros)

  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' }
    },
    legend: {
      data: ['专注时长(分钟)', '番茄钟数量']
    },
    grid: {
      left: '3%',
      right: '4%',
      bottom: '3%',
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: dates,
      axisLabel: {
        rotate: dateRange.value === 'month' ? 45 : 0
      }
    },
    yAxis: [
      {
        type: 'value',
        name: '专注时长(分钟)',
        position: 'left'
      },
      {
        type: 'value',
        name: '番茄钟数量',
        position: 'right'
      }
    ],
    series: [
      {
        name: '专注时长(分钟)',
        type: 'bar',
        data: minutes,
        itemStyle: {
          color: '#667eea',
          borderRadius: [4, 4, 0, 0]
        }
      },
      {
        name: '番茄钟数量',
        type: 'line',
        yAxisIndex: 1,
        data: pomodoros,
        smooth: true,
        lineStyle: {
          color: '#f5576c',
          width: 2
        },
        symbol: 'circle',
        symbolSize: 8,
        itemStyle: {
          color: '#f5576c'
        }
      }
    ]
  }

  trendChart.setOption(option)
}

onMounted(() => {
  loadStatistics()
  window.addEventListener('resize', () => {
    if (trendChart) trendChart.resize()
  })
})

onUnmounted(() => {
  if (trendChart) {
    trendChart.dispose()
  }
  window.removeEventListener('resize', () => {})
})
</script>

