import { ref, reactive, computed, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import Header from '@/components/common/Header.vue'
import { useUserStore } from '@/stores/user'
import { updateUserInfo, updatePassword } from '@/api/user'

const userStore = useUserStore()
const activeTab = ref('info')
const infoLoading = ref(false)
const passwordLoading = ref(false)
const infoFormRef = ref()
const passwordFormRef = ref()

const userInfo = computed(() => userStore.userInfo)

const infoForm = reactive({
  nickname: '',
  email: '',
  avatar: ''
})

const infoRules = {
  email: [
    { type: 'email', message: '请输入正确的邮箱地址', trigger: 'blur' }
  ]
}

const passwordForm = reactive({
  oldPassword: '',
  newPassword: '',
  confirmPassword: ''
})

const validateConfirmPassword = (rule, value, callback) => {
  if (value !== passwordForm.newPassword) {
    callback(new Error('两次输入的密码不一致'))
  } else {
    callback()
  }
}

const passwordRules = {
  oldPassword: [
    { required: true, message: '请输入原密码', trigger: 'blur' }
  ],
  newPassword: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { min: 6, max: 20, message: '密码长度6-20位', trigger: 'blur' }
  ],
  confirmPassword: [
    { required: true, message: '请确认密码', trigger: 'blur' },
    { validator: validateConfirmPassword, trigger: 'blur' }
  ]
}

const updateInfo = async () => {
  if (!infoFormRef.value) return

  await infoFormRef.value.validate(async (valid) => {
    if (valid) {
      infoLoading.value = true
      try {
        const res = await updateUserInfo(infoForm)
        if (res.code === 200) {
          ElMessage.success('更新成功')
          await userStore.fetchUserInfo()
          infoForm.nickname = userStore.userInfo?.nickname || ''
          infoForm.email = userStore.userInfo?.email || ''
          infoForm.avatar = userStore.userInfo?.avatar || ''
        } else {
          ElMessage.error(res.message)
        }
      } catch (error) {
        ElMessage.error('更新失败')
      } finally {
        infoLoading.value = false
      }
    }
  })
}

const updatePassword = async () => {
  if (!passwordFormRef.value) return

  await passwordFormRef.value.validate(async (valid) => {
    if (valid) {
      passwordLoading.value = true
      try {
        const res = await updatePassword({
          oldPassword: passwordForm.oldPassword,
          newPassword: passwordForm.newPassword
        })
        if (res.code === 200) {
          ElMessage.success('密码修改成功，请重新登录')
          passwordForm.oldPassword = ''
          passwordForm.newPassword = ''
          passwordForm.confirmPassword = ''
          setTimeout(() => {
            userStore.logout()
            window.location.href = '/login'
          }, 1500)
        } else {
          ElMessage.error(res.message)
        }
      } catch (error) {
        ElMessage.error('修改失败')
      } finally {
        passwordLoading.value = false
      }
    }
  })
}

onMounted(() => {
  if (userStore.userInfo) {
    infoForm.nickname = userStore.userInfo.nickname || ''
    infoForm.email = userStore.userInfo.email || ''
    infoForm.avatar = userStore.userInfo.avatar || ''
  }
})
</script>

