        <el-date-picker
          v-model="form.deadline"
          type="datetime"
          placeholder="选择截止时间"
          format="YYYY-MM-DD HH:mm:ss"
          value-format="YYYY-MM-DD HH:mm:ss"
        />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="handleClose">取消</el-button>
      <el-button type="primary" @click="handleSubmit" :loading="submitting">
        确定
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { createTask, updateTask } from '@/api/task'

const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  },
  task: {
    type: Object,
    default: null
  }
})

const emit = defineEmits(['update:visible', 'success'])

const formRef = ref()
const submitting = ref(false)

const isEdit = computed(() => !!props.task)

const form = reactive({
  title: '',
  description: '',
  priority: 2,
  estimatedPomodoros: 1,
  deadline: null
})

const rules = {
  title: [
    { required: true, message: '请输入任务标题', trigger: 'blur' },
    { max: 200, message: '标题不能超过200个字符', trigger: 'blur' }
  ],
  priority: [
    { required: true, message: '请选择优先级', trigger: 'change' }
  ],
  estimatedPomodoros: [
    { required: true, message: '请填写预估番茄钟数量', trigger: 'change' }
  ]
}

watch(() => props.visible, (val) => {
  if (val && props.task) {
    // 编辑模式，填充数据
    form.title = props.task.title
    form.description = props.task.description || ''
    form.priority = props.task.priority
    form.estimatedPomodoros = props.task.estimatedPomodoros
    form.deadline = props.task.deadline
  } else if (val && !props.task) {
    // 新建模式，重置表单
    resetForm()
  }
})

const resetForm = () => {
  form.title = ''
  form.description = ''
  form.priority = 2
  form.estimatedPomodoros = 1
  form.deadline = null
}

const handleClose = () => {
  emit('update:visible', false)
  resetForm()
  if (formRef.value) {
    formRef.value.resetFields()
  }
}

const handleSubmit = async () => {
  if (!formRef.value) return

  await formRef.value.validate(async (valid) => {
    if (valid) {
      submitting.value = true
      try {
        let res
        if (isEdit.value) {
          res = await updateTask({
            id: props.task.id,
            ...form
          })
        } else {
          res = await createTask(form)
        }

        if (res.code === 200) {
          ElMessage.success(isEdit.value ? '更新成功' : '创建成功')
          emit('success')
          handleClose()
        } else {
          ElMessage.error(res.message)
        }
      } catch (error) {
        ElMessage.error('操作失败')
      } finally {
        submitting.value = false
      }
    }
  })
}
</script>

