## 六、任务状态管理Store

### 6.1 stores/task.js

```javascript
import { defineStore } from 'pinia'
import { getTaskList, createTask, updateTask, deleteTask, completeTask } from '@/api/task'

export const useTaskStore = defineStore('task', {
  state: () => ({
    tasks: [],
    total: 0,
    currentPage: 1,
    pageSize: 10,
    filterStatus: null
  }),

  actions: {
    async fetchTaskList(params = {}) {
      try {
        const queryParams = {
          page: this.currentPage,
          size: this.pageSize,
          status: this.filterStatus,
          ...params
        }
        const res = await getTaskList(queryParams)
        if (res.code === 200) {
          this.tasks = res.data.records
          this.total = res.data.total
          return { success: true, data: res.data }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    async createTask(data) {
      try {
        const res = await createTask(data)
        if (res.code === 200) {
          await this.fetchTaskList()
          return { success: true }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    async updateTask(data) {
      try {
        const res = await updateTask(data)
        if (res.code === 200) {
          await this.fetchTaskList()
          return { success: true }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    async deleteTask(id) {
      try {
        const res = await deleteTask(id)
        if (res.code === 200) {
          await this.fetchTaskList()
          return { success: true }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    async completeTask(id) {
      try {
        const res = await completeTask(id)
        if (res.code === 200) {
          await this.fetchTaskList()
          return { success: true }
        }
        return { success: false, message: res.message }
      } catch (error) {
        return { success: false, message: error.message }
      }
    },

    setFilterStatus(status) {
      this.filterStatus = status
      this.currentPage = 1
      this.fetchTaskList()
    },

    setPage(page) {
      this.currentPage = page
      this.fetchTaskList()
    },

    setPageSize(size) {
      this.pageSize = size
      this.currentPage = 1
      this.fetchTaskList()
    }
  }
})
