## 解决方案四：使用注解方式配置CORS（快速测试）

在Controller上添加 `@CrossOrigin` 注解：

```java
package com.pomodoro.controller;

import com.pomodoro.common.Result;
import com.pomodoro.dto.request.LoginRequest;
import com.pomodoro.dto.request.RegisterRequest;
import com.pomodoro.dto.response.LoginResponse;
import com.pomodoro.dto.response.UserInfoResponse;
import com.pomodoro.service.UserService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/user")
@CrossOrigin(origins = "*", allowedHeaders = "*", methods = {RequestMethod.GET, RequestMethod.POST, RequestMethod.PUT, RequestMethod.DELETE, RequestMethod.OPTIONS})
@RequiredArgsConstructor
public class UserController {

    private final UserService userService;

    @PostMapping("/register")
    public Result<Object> register(@Valid @RequestBody RegisterRequest request) {
        return userService.register(request);
    }

    @PostMapping("/login")
    public Result<LoginResponse> login(@Valid @RequestBody LoginRequest request) {
        return userService.login(request);
    }

    @GetMapping("/info")
    public Result<UserInfoResponse> getUserInfo(HttpServletRequest request) {
        Long userId = (Long) request.getAttribute("userId");
        return userService.getUserInfo(userId);
    }

    @PutMapping("/update")
    public Result<Object> updateUserInfo(HttpServletRequest request,
                                         @RequestParam(required = false) String nickname,
                                         @RequestParam(required = false) String email,
                                         @RequestParam(required = false) String avatar) {
        Long userId = (Long) request.getAttribute("userId");
        return userService.updateUserInfo(userId, nickname, email, avatar);
    }

    @PutMapping("/password")
    public Result<Object> updatePassword(HttpServletRequest request,
                                         @RequestParam String oldPassword,
                                         @RequestParam String newPassword) {
        Long userId = (Long) request.getAttribute("userId");
        return userService.updatePassword(userId, oldPassword, newPassword);
    }
}
