#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MEM_SIZE 640  // 总内存大小 640KB
#define FREE 0        // 空闲分区标志
#define ALLOCATED 1   // 已分配分区标志

// 分区结构体
typedef struct Block {
    int start;          // 起始地址
    int size;           // 分区大小
    int state;          // 状态: FREE 或 ALLOCATED
    struct Block *next; // 指向下一个分区
} Block;

Block *head = NULL; // 空闲分区链表的头指针

// 初始化内存: 整个内存为一个空闲块
void init_memory() {
    head = (Block *)malloc(sizeof(Block));
    head->start = 0;
    head->size = MEM_SIZE;
    head->state = FREE;
    head->next = NULL;
}

// 显示当前内存分配情况
void display_memory() {
    Block *p = head;
    printf("\n========== 内存分区情况 ==========\n");
    printf("起始地址\t大小(KB)\t状态\n");

    while (p != NULL) {
        printf("%d\t\t%d\t\t%s\n", p->start, p->size, 
               (p->state == FREE) ? "空闲" : "已分配");
        p = p->next;
    }
    printf("===================================\n");
}

// 合并相邻的空闲分区
void merge_free_blocks() {
    Block *p = head;
    while (p != NULL && p->next != NULL) {
        if (p->state == FREE && p->next->state == FREE) {
            // 合并两个相邻空闲块
            p->size += p->next->size;
            Block *temp = p->next;
            p->next = temp->next;
            free(temp);
        } else {
            p = p->next;
        }
    }
}

// 首次适应算法分配内存
int first_fit_allocate(int size, const char *process_name) {
    Block *p = head;
    while (p != NULL) {
        if (p->state == FREE && p->size >= size) {
            // 找到合适的空闲块
            if (p->size == size) {
                // 完全占用
                p->state = ALLOCATED;
            } else {
                // 分割空闲块
                Block *new_block = (Block *)malloc(sizeof(Block));
                new_block->start = p->start + size;
                new_block->size = p->size - size;
                new_block->state = FREE;
                new_block->next = p->next;

                p->size = size;
                p->state = ALLOCATED;
                p->next = new_block;
            }
            printf("首次适应算法: 分配 %dKB 成功\n", size);
            return 1;
        }
        p = p->next;
    }
    printf("首次适应算法: 分配 %dKB 失败，内存不足\n", size);
    return 0;
}

// 最佳适应算法分配内存
int best_fit_allocate(int size, const char *process_name) {
    Block *p = head;
    Block *best = NULL;
    int min_size = MEM_SIZE + 1;

    // 查找最合适的空闲块
    while (p != NULL) {
        if (p->state == FREE && p->size >= size && p->size < min_size) {
            min_size = p->size;
            best = p;
        }
        p = p->next;
    }

    if (best != NULL) {
        if (best->size == size) {
            best->state = ALLOCATED;
        } else {
            Block *new_block = (Block *)malloc(sizeof(Block));
            new_block->start = best->start + size;
            new_block->size = best->size - size;
            new_block->state = FREE;
            new_block->next = best->next;

            best->size = size;
            best->state = ALLOCATED;
            best->next = new_block;
        }
        printf("最佳适应算法: 分配 %dKB 成功\n", size);
        return 1;
    }
    printf("最佳适应算法: 分配 %dKB 失败，内存不足\n", size);
    return 0;
}

// 最坏适应算法分配内存
int worst_fit_allocate(int size, const char *process_name) {
    Block *p = head;
    Block *worst = NULL;
    int max_size = -1;

    // 查找最大的空闲块
    while (p != NULL) {
        if (p->state == FREE && p->size >= size && p->size > max_size) {
            max_size = p->size;
            worst = p;
        }
        p = p->next;
    }

    if (worst != NULL) {
        if (worst->size == size) {
            worst->state = ALLOCATED;
        } else {
            Block *new_block = (Block *)malloc(sizeof(Block));
            new_block->start = worst->start + size;
            new_block->size = worst->size - size;
            new_block->state = FREE;
            new_block->next = worst->next;

            worst->size = size;
            worst->state = ALLOCATED;
            worst->next = new_block;
        }
        printf("最坏适应算法: 分配 %dKB 成功\n", size);
        return 1;
    }
    printf("最坏适应算法: 分配 %dKB 失败，内存不足\n", size);
    return 0;
}

// 释放内存块（通过起始地址）
int free_memory(int start, int size) {
    Block *p = head;
    while (p != NULL) {
        if (p->start == start && p->state == ALLOCATED && p->size == size) {
