### C 语言完整代码

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define INSTRUCTION_COUNT 320
#define PAGE_COUNT 32        // 虚拟内存32页
#define INSTRUCTIONS_PER_PAGE 10
#define MAX_FRAMES 32        // 最大物理块数
#define MIN_FRAMES 4         // 最小物理块数

// 全局变量存放页面序列
int page_sequence[INSTRUCTION_COUNT];

// ---------------------------
// 1. 生成指令序列并转换为页面序列
// ---------------------------
void generate_page_sequence() {
    // 生成320条随机指令 (0-319范围内)
    int instructions[INSTRUCTION_COUNT];
    for (int i = 0; i < INSTRUCTION_COUNT; i++) {
        instructions[i] = rand() % 320;
    }

    // 将指令按每页10条转换为页面号
    for (int i = 0; i < INSTRUCTION_COUNT; i++) {
        page_sequence[i] = instructions[i] / INSTRUCTIONS_PER_PAGE;
    }
}

// ---------------------------
// 2. 算法实现
// ---------------------------

// 2.1 先进先出 (FIFO)
int fifo_algorithm(int frames_count) {
    int memory[frames_count];
    for (int i = 0; i < frames_count; i++) memory[i] = -1; // -1表示空
    int page_faults = 0;
    int head = 0; // 指向最老的页面位置

    for (int i = 0; i < INSTRUCTION_COUNT; i++) {
        int page = page_sequence[i];
        bool found = false;

        // 检查页面是否已在内存中
        for (int j = 0; j < frames_count; j++) {
            if (memory[j] == page) {
                found = true;
                break;
            }
        }

        if (!found) {
            page_faults++;
            memory[head] = page;
            head = (head + 1) % frames_count; // 循环队列
        }
    }
    return page_faults;
}

// 2.2 最近最久未使用 (LRU)
int lru_algorithm(int frames_count) {
    int memory[frames_count];
    // 记录每个物理块中页面最后一次被访问的时间戳
    int last_used[frames_count]; 
    for (int i = 0; i < frames_count; i++) {
        memory[i] = -1;
        last_used[i] = -1;
    }
    int page_faults = 0;

    for (int i = 0; i < INSTRUCTION_COUNT; i++) {
        int page = page_sequence[i];
        bool found = false;

        // 查找页面
        for (int j = 0; j < frames_count; j++) {
            if (memory[j] == page) {
                found = true;
                last_used[j] = i; // 更新使用时间
                break;
            }
        }

        if (!found) {
            page_faults++;

            // 查找是否有空位
            int empty_index = -1;
            for (int j = 0; j < frames_count; j++) {
                if (memory[j] == -1) {
                    empty_index = j;
                    break;
                }
            }

            if (empty_index != -1) {
                // 有空位，直接放入
                memory[empty_index] = page;
                last_used[empty_index] = i;
            } else {
                // 无空位，找到最久未使用的
                int lru_index = 0;
                int min_time = last_used[0];
                for (int j = 1; j < frames_count; j++) {
                    if (last_used[j] < min_time) {
                        min_time = last_used[j];
                        lru_index = j;
                    }
                }
                // 置换
                memory[lru_index] = page;
                last_used[lru_index] = i;
            }
        }
    }
    return page_faults;
}

// 2.3 最优置换算法 (OPT)
int opt_algorithm(int frames_count) {
    int memory[frames_count];
    for (int i = 0; i < frames_count; i++) memory[i] = -1;
    int page_faults = 0;

    for (int i = 0; i < INSTRUCTION_COUNT; i++) {
        int page = page_sequence[i];
        bool found = false;

        // 查找
        for (int j = 0; j < frames_count; j++) {
            if (memory[j] == page) {
                found = true;
                break;
            }
        }

        if (!found) {
            page_faults++;

            // 查找空位
            int empty_index = -1;
            for (int j = 0; j < frames_count; j++) {
                if (memory[j] == -1) {
                    empty_index = j;
                    break;
                }
            }

            if (empty_index != -1) {
                memory[empty_index] = page;
            } else {
                // 需要置换：找到未来最长时间才使用的页
                int replace_index = -1;
                int furthest_use = -1;

                for (int j = 0; j < frames_count; j++) {
                    int current_page = memory[j];
                    int next_use = -1;

                    // 搜索未来位置
                    for (int k = i + 1; k < INSTRUCTION_COUNT; k++) {
                        if (page_sequence[k] == current_page) {
                            next_use = k;
                            break;
                        }
                    }

                    // 如果页面未来不再使用，直接标记为最近替换候选
                    if (next_use == -1) {
                        replace_index = j;
                        break; 
                    }

                    // 找到最远的那个
                    if (next_use > furthest_use) {
                        furthest_use = next_use;
                        replace_index = j;
                    }
                }

                memory[replace_index] = page;
            }
        }
    }
    return page_faults;
}

// ---------------------------
// 3. 主函数
// ---------------------------
int main() {
    srand((unsigned)time(NULL));

    printf("Generating random page sequence...\n");
    generate_page_sequence();

    printf("Page Frames | FIFO Hit Rate | LRU Hit Rate | OPT Hit Rate\n");
    printf("--------------------------------------------------------\n");

    // 遍历 4 到 32 页的内存容量
    for (int frames = MIN_FRAMES; frames <= MAX_FRAMES; frames++) {
        // 计算缺页次数
        int fifo_faults = fifo_algorithm(frames);
        int lru_faults = lru_algorithm(frames);
        int opt_faults = opt_algorithm(frames);

        // 计算命中率: 1 - (缺页次数 / 总访问次数)
        float fifo_hit = 1.0f - (float)fifo_faults / INSTRUCTION_COUNT;
        float lru_hit = 1.0f - (float)lru_faults / INSTRUCTION_COUNT;
        float opt_hit = 1.0f - (float)opt_faults / INSTRUCTION_COUNT;

        printf("%4d pages     FIFO:%.4f   LRU:%.4f   OPT:%.4f\n", 
               frames, fifo_hit, lru_hit, opt_hit);
    }

    printf("--------------------------------------------------------\n");
    printf("Simulation Complete.\n");

    return 0;
}
```

### 代码运行说明

1.  **编译与运行**：
    将代码保存为 `page_replacement.c`，然后使用 C 编译器编译（例如 GCC）：
    ```bash
    gcc page_replacement.c -o page_replacement
    ./page_replacement
    ```

2.  **输出结果**：
    程序会输出类似你截图的表格，每行对应一个内存容量（4到32页），每列分别是三种算法的命中率。命中率会保留4位小数。
    *注意：由于指令是随机生成的，每次运行结果会略有不同，但趋势一致（内存越大，命中率越高；OPT >= LRU >= FIFO）。*

3.  **局部性模拟（可选）**：
    你在题目中提到“通过随机数产生指令序列”。我代码中使用的 `rand() % 320` 是最直接的生成方式。
    如果老师要求严格按照“局部性原理”（比如指令访问集中在某个区域附近），你可以修改 `generate_page_sequence()` 函数，加入一个偏移量逻辑来模拟循环或跳跃，但这通常在随机测试中不是必须的，因为随机序列已经覆盖了全范围。

很好，选**方案1（极致性能）**继续深化面向对象，这是最挑战但也最有意思的方向。核心策略是：**在零/极低开销的前提下，选择性实现Java风格OOP，放弃那些注定昂贵的特性**。

