### 3.3 偏移计算规则

```c
// 编译器生成的偏移常量 (示例)
#define DOG_OFFSET_VTABLE_ANIMAL       16
#define DOG_OFFSET_ITABLE_RUNNABLE     24
#define DOG_OFFSET_ITABLE_SERIALIZABLE 32
#define DOG_OFFSET_AGE                 40
#define DOG_OFFSET_LEGS                48

// 接口表内偏移
#define ITABLE_RUNNABLE_RUN_OFFSET      0
#define ITABLE_RUNNABLE_STOP_OFFSET     8
#define ITABLE_SERIALIZABLE_SERIALIZE_OFFSET   0
#define ITABLE_SERIALIZABLE_DESERIALIZE_OFFSET 8
