// IR类型系统
#[derive(Debug, Clone, PartialEq)]
pub enum IRType {
    Void,
    Integer { bits: u32, signed: bool },  // i8, i16, i32, i64
    Float { bits: u32 },                   // f32, f64
    Pointer(Box<IRType>),
    Struct(String, Vec<IRType>),
    Array(Box<IRType>, u64),
    Function(Vec<IRType>, Box<IRType>),
    VTable(String),                        // 虚表类型
    ITable(String),                        // 接口表类型
    Object,                                // GC对象
}

// IR值 (SSA)
#[derive(Debug, Clone)]
pub struct IRValue {
    pub name: String,
    pub typ: IRType,
    pub id: u32,
}

// IR指令
#[derive(Debug)]
pub enum IRInstruction {
    // 内存操作
    Alloca(IRType),                    // 栈分配
    Load(IRValue),                     // 加载
    Store(IRValue, IRValue),           // 存储
    GEP(IRValue, Vec<IRValue>),        // 地址计算

    // 算术运算
    Add(IRValue, IRValue),
    Sub(IRValue, IRValue),
    Mul(IRValue, IRValue),
    Div(IRValue, IRValue),
    Mod(IRValue, IRValue),

    // 比较运算
    ICmp(CmpOp, IRValue, IRValue),
    FCmp(CmpOp, IRValue, IRValue),

    // 类型转换
    Cast(IRValue, IRType),
    Bitcast(IRValue, IRType),

    // 控制流
    CondBr(IRValue, String, String),   // 条件跳转
    Br(String),                         // 无条件跳转
    Ret(Option<IRValue>),               // 返回

    // 函数调用
    Call(String, Vec<IRValue>),

    // GC相关
    GcAlloc(IRType),                   // GC分配
    Retain(IRValue),                   // 引用计数+1
    Release(IRValue),                  // 引用计数-1
    WeakRefCreate(IRValue),            // 创建弱引用
    WeakRefGet(IRValue),               // 获取弱引用

    // 虚表/接口调用
    VCall(IRValue, u32, Vec<IRValue>), // 虚方法调用
    ICall(IRValue, u32, Vec<IRValue>), // 接口方法调用

    // 特殊
    Phi(Vec<(IRValue, String)>),       // φ函数
    Unreachable,
    Debug(String),
}
