## 六、运行时库 (runtime.S)

```assembly
; runtime/runtime.S
section .text
global gc_alloc, retain, release, weak_ref_create

; 函数: gc_alloc(size_t size) -> void*
gc_alloc:
    push rbp
    mov rbp, rsp

    ; 调用malloc
    call malloc wrt ..plt

    ; 初始化对象头
    test rax, rax
    jz .alloc_failed

    ; ref_count = 1
    mov dword [rax], 1

    ; type_info = NULL (稍后设置)
    mov qword [rax + 4], 0

    ; flags = 0
    mov word [rax + 12], 0

    ; padding = 0
    mov word [rax + 14], 0

.alloc_failed:
    pop rbp
    ret

; 函数: retain(void* obj)
retain:
    test rdi, rdi
    jz .ret

    ; atomic increment
    lock inc dword [rdi]

.ret:
    ret

; 函数: release(void* obj)
release:
    test rdi, rdi
    jz .ret

    ; atomic decrement
    lock dec dword [rdi]
    jnz .ret

    ; ref_count == 0, 释放对象
    ; 先调用析构函数
    mov rax, [rdi + 8]      ; 加载type_info
    test rax, rax
    jz .skip_dtor

    mov rax, [rax + 24]     ; dtor offset
    test rax, rax
    jz .skip_dtor

    call rax

.skip_dtor:
    ; 释放内存
    mov rdi, rdi
    call free wrt ..plt

.ret:
    ret

; 全局对象 (GC根集)
section .data
global __gc_root_set
__gc_root_set:
    dq 0  ; 根集链表头
```

